pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize the score.
    // Base score is the residual space after placement.
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the post_residual is small (e.g., < 10), it is likely 
    // to become unusable "fragmentation" waste. Penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // 2. Lookahead optimization: If the next item fits into the current post_residual, 
    // reward this bin to encourage packing pairs.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }

    // 3. Global pressure: As we approach the end of the stream, prioritize closing 
    // bins (lower residual) over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * progress * 5.0;

    // 4. New bin logic: If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // Penalize this heavily unless it is the only way to avoid a tiny, unusable gap.
    if bin_residual == bin_capacity {
        // Opening a new bin is a last resort. 
        // We set the cost to be relative to the average efficiency of current bins.
        score = 40.0 + (mean_residual * 0.5);
    }

    // 5. If this is the only bin that can fit the item, prioritize it to avoid 
    // forcing a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize small gaps (fragmentation) that are too small for common items,
    // but reward filling bins tightly as we approach the end of the stream.
    let fragmentation_penalty = if post > 0.0 && post < 15.0 {
        20.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Coupling: If we have many open bins, prioritize finishing off the fullest ones.
    // As the stream progresses, favor tighter packing (lower post_residual).
    let capacity_pressure = (open_bins_count as f64) * (1.0 - progress);

    // Lookahead logic: If the next item is large, favor keeping larger gaps open.
    // If the next item is small, favor filling the current bin.
    let lookahead_mod = if next_item_size > 0 {
        let diff = (next_item_size as f64) - (post as f64);
        if diff > 0.0 { 15.0 } else { -5.0 }
    } else {
        0.0
    };

    // Base score is the residual space; we want to minimize this (Best Fit).
    // We add penalties to steer away from creating "useless" small holes.
    let mut score = post + fragmentation_penalty + capacity_pressure + lookahead_mod;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy premium
    // to open it only when necessary.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current packing options are very poor (high residuals)
        // or if we are nearing the end of the stream and need to clear out remaining items.
        score = 45.0 + (progress * 20.0) + (mean_residual * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best Fit (minimizing post_residual)
    // 2. Penalty for opening new bins: if bin_residual == bin_capacity, this is a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is already very tight (< 15)
        // or if we are forced to (fitting_bins_count == 0).
        if fitting_bins_count > 0 && mean_residual > 15.0 {
            score += 1000.0;
        } else {
            score += 45.0; // Moderate cost to open a new bin
        }
    }

    // 3. Harmonic Logic: Favor residuals that are multiples of common item sizes (e.g., 20, 25, 33)
    // to leave space for future items.
    let harmonic_penalty = (post_residual % 20) as f64 * 0.5;
    score += harmonic_penalty;

    // 4. Lookahead coupling: If next_item_size is large, avoid creating a post_residual
    // that is slightly smaller than the next item (creating "dead space").
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 5 {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // Reward if post_residual is a perfect fit for the next item
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 5. Progression awareness: As we approach the end of the stream, tighten requirements
    // to avoid leaving too many bins half-empty.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    // 6. Penalty for creating "unusable" tiny fragments (1-9)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
