    // we apply a cost that increases as we approach the end of the stream.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 50.0);
    }

    // If this is the only bin that can fit the item, we lower the score to prioritize
    // using existing capacity over opening a new bin, unless the fit is extremely poor.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Coupling with mean_residual: If our current bin is significantly worse than the 
