    if post > mean_residual {
        score += (post - mean_residual) * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but not zero (fragmentation)
    // We favor "Perfect Fit" (residual 0) or leaving enough room for a future item.
    if post_residual > 0 {
        score += (bin_capacity as f64 / (post_residual as f64 + 1.0)).powf(1.5);
    }

    // 2. Lookahead Coupling: If next_item_size is known, penalize bin choice if it prevents 
    // a potential perfect match for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This bin cannot fit the next item; penalize proportional to the wasted capacity
            score += 25.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            // This bin can fit the next item; reward slightly
            score -= 10.0;
        }
    }

    // 3. Density Balancing: If we are near the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 2.0);

    // 4. New Bin Thresholding: Discourage opening new bins unless the current fit is extremely poor.
    // If bin_residual == bin_capacity, this is the "New Bin" call.
    if bin_residual == bin_capacity {
        // Only pick a new bin if the average residual is already quite low (bins are full).
        score += 40.0 - (mean_residual * 0.5);
    } else {
        // If we have very few fitting options, prioritize using existing bins.
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
    }

    // 5. Modulo-based Harmonic Class Preference:
    // Align residuals with common item size factors to keep bins "flexible".
    let harmonic_mod = (post_residual % 25) as f64;
    score += harmonic_mod * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residual (tighter packing)
    // We penalize larger post_residuals to keep bins full.

    // 2. Lookahead Penalty: If the next item is large, avoid leaving a small gap that can't fit it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a bin that cannot accommodate the known next item
            score += 150.0 * (next_item_size as f64 / (post_residual + 1) as f64);
        }
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // unless the fit in existing bins is objectively terrible.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily discourage opening a new bin if other bins can fit the item
            score += 120.0 + (mean_residual * 0.5);
        } else {
            // If no other bin fits, this is the baseline for opening a new bin
            score = 60.0;
        }
    } else {
        // 4. Fragment Avoidance:
        // Penalize residuals that are too small to be useful (e.g., < 10)
        // because they often become "dead space".
        if post_residual < 10 && post_residual > 0 {
            score += 40.0;
        }

        // 5. Global State Coupling:
        // If we are late in the sequence, prioritize finishing off existing bins
        // to minimize the final count.
        let progress = step_index as f64 / total_items as f64;
        score -= progress * (bin_capacity - post_residual) as f64 * 0.2;
    }

    // 6. Last Chance Modifier:
    // If this is the only bin that fits the item (fitting_bins_count == 1),
    // give it a slight boost to ensure we don't accidentally open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Harmonic classes logic.
    // Goal: Minimize fragmentation by preferring "tight" fits (low post_residual) 
    // while biasing against leaving small, unusable slivers (< 10).

    let mut score = post_residual as f64;

    // 1. Penalty for creating "Dead Space" (slivers < 10 are rarely useful)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Harmonic Class Alignment: Favor bins where the post_residual is a multiple of 
    // common item size classes (e.g., 20, 25, 33) to maximize future compatibility.
    let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_penalty * 0.5;

    // 3. Lookahead Logic: If the next item fits into the current post_residual,
    // strongly incentivize this bin to preserve bin density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Scarcity Constraint: If this is the only fitting bin, lower the threshold 
    // for accepting a "bad" fit to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // 5. Global Capacity Pressure: As the stream progresses, prioritize filling 
    // existing bins more aggressively to consolidate space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 2.0);

    // 6. New Bin Threshold: If bin_residual == bin_capacity, we are evaluating a new bin.
    // We only want to open a new bin if the current "best" fit is extremely poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high.
        score = 85.0 - (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // 2. Lookahead mechanism: if post_residual is close to next_item_size, reward it
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        // If the current placement leaves space perfectly for the next item, heavily reward it
        if post_residual >= next_item_size {
            score -= (100.0 - diff) * 0.5;
        } else {
            // Penalize placements that make it impossible to fit the next item
            score += 50.0;
        }
    }

    // 3. New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity), only pick it if current open bins are "bad"
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Only open a new bin if the average residual of open bins is very low, 
            // indicating they are nearly full and likely to cause fragmentation
            score += (mean_residual * 2.0).min(40.0);
        }
    } else {
        // 4. Fragmentation management: 
        // Penalize leaving very small residuals (e.g., 1-9) that are unlikely to be filled
        if post_residual > 0 && post_residual < 10 {
            score += 30.0;
        }

        // 5. Urgency: If this is the only bin that fits, prioritize it
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 6. Progressive tightening: As we approach the end of the stream, prioritize filling existing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We prioritize bins that result in the smallest remaining gap.
    score += (post_residual as f64).powf(1.1);

    // 2. Lookahead Matching: If the next item fits perfectly in the post_residual, 
    // we strongly prefer this bin to avoid fragmentation.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_diff) * 2.5;
    }

    // 3. Fragmentation Avoidance: If the post_residual is too small to fit any likely future item 
    // (e.g., < 10), we penalize it, unless it is a perfect zero-waste fit.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. Strategic New Bin Opening:
    // If this is a new bin (bin_residual == bin_capacity), only choose it if 
    // the existing fitting bins are so full that they force bad placement.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is high, but decreases as we struggle to find 
        // a good fit in existing bins (using fitting_bins_count).
        score += 85.0 - (fitting_bins_count as f64 * 5.0);
    }

    // 5. Global Balance: If the current bin's residual is significantly worse than the 
    // mean_residual of other bins, penalize it to encourage consolidation.
    if (bin_residual as f64) > mean_residual + 15.0 {
        score += 20.0;
    }

    // 6. Stream Progress: As we approach the end of the stream, prioritize 
    // filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 40.0;
    }

