}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "slivers" (small, unusable residuals). 
    // We penalize residuals between 1 and 9 heavily, as they are unlikely to fit future items.
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - post / 10.0);
    }

    // Lookahead interaction: If the next item is large and the current placement 
    // makes it impossible to fit, penalize the bin.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += 25.0 * (1.0 - progress);
    }

    // Dynamic pressure: As the stream progresses, favor packing tighter (lower residual).
    // We penalize having many bins open relative to the mean residual.
    let density_penalty = (open_bins_count as f64 * (1.0 - mean_residual / bin_capacity as f64)) * progress * 10.0;
    score += density_penalty;

    // If this is the only bin that can fit the item, give it a significant priority boost (negative bias).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New Bin Thresholding:
    // If we are considering a new bin (bin_residual == bin_capacity), 
    // we only return a low score if the current state of bins is highly inefficient.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite high, 
        // to avoid fragmentation.
        score = 35.0 + (mean_residual * 0.5) - (progress * 10.0);
    }

