        // the global mean, it might be creating "dust" (unusable small space).
        // We reward bins that stay close to the current average packing density.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // 5. Final constraint: ensure we don't prefer a new bin if the item fits perfectly elsewhere.
    if fitting_bins_count > 0 && bin_residual == bin_capacity {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
