    // 2. Lookahead Coupling: If a future item exists, prioritize bins that 
    // leave enough space for it (Best-Fit-Decreasing logic).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can accommodate the next item
        } else if post_residual > 0 {
            score += 10.0; // Penalize bins that block the next item
        }
