pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily favor bins where post_residual is minimized.
    // Penalty for leaving large gaps that are hard to fill.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Reward bins that become highly "compatible" for future items.
    // If post_residual is small, it's often a "dead" bin. If it's a multiple of 
    // common item sizes, it's a "live" bin.
    if post_residual > 0 {
        // Reward post_residuals that are likely to fit next_item_size
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 2.5;
        }

        // Harmonic penalty: avoid small remainders (1-5) which are usually useless
        if post_residual < 6 {
            score += 50.0;
        }
    }

    // 3. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), only open it if 
    // the existing fitting bins result in very poor residuals.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin
        score = 45.0; 

        // If we have many open bins, penalize opening another one
        score += (open_bins_count as f64) * 2.0;

        // If the current mean_residual is already small, opening a new bin is inefficient
        if mean_residual < 20.0 {
