    // 2. Lookahead Coupling: If the next item is large, prioritize keeping space open.
    // If next_item_size is large (e.g., > 50), penalize bins that would make it impossible to fit.
    if next_item_size > 50 && post_residual < next_item_size {
        score += 80.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is excellent.
    // If this is a new bin (bin_residual == bin_capacity), add a threshold cost.
    if bin_residual == bin_capacity {
        score += 45.0;
        // As the stream progresses, make opening a new bin slightly more expensive
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // 4. Fitting Count Utility: If this is the only bin that can fit the item, 
    // lower the score to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Mean Residual Alignment: Penalize deviations from the mean to keep bin usage uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Aggressive 2-step lookahead matching.
    // Lower score is better.
    let mut score = post_residual as f64;

    // 1. Penalty for opening new bins prematurely:
    // If this is the new bin candidate, add a penalty based on current capacity utilization.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 2.0);
    }

    // 2. Lookahead matching:
    // If the next item fits perfectly into the post_residual, reward this bin heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // If post_residual is slightly larger than next_item, prioritize this bin
            // to keep the "gap" tight for the next step.
            score -= (100.0 - post_residual as f64) * 0.1;
        } else {
            // Penalize if post_residual is too small for the next item, 
            // especially if this was our only fitting bin.
            if fitting_bins_count == 1 {
                score += 20.0;
            }
        }
    }

    // 3. Balancing vs Mean Residual:
    // If the bin's resulting residual is significantly higher than the global mean,
    // it likely leads to fragmentation. Penalize bins that create "loose" ends.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 4. Progress-based scaling:
    // As we approach the end of the stream, be more conservative with opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (progress * 30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize small fragments (1-9)
    // that are unlikely to accommodate future items.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // strongly favor this bin to maximize packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 3. Global State Balancing: Avoid fragmentation by penalizing bins that deviate
    // significantly from the mean residual of existing bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * deviation;

    // 4. New Bin Thresholding: Dynamic pressure to open new bins.
    // As the stream progresses, it becomes safer to open a new bin if the best
    // available fit is poor, to save space for potentially large items.
    if is_new_bin {
        // Base penalty for opening a new bin
        let mut new_bin_penalty = 35.0;

        // If we have very few open bins, opening a new one is less costly
        if open_bins_count < 3 {
            new_bin_penalty -= 10.0;
        }

        // Late-stage optimization: be more conservative with new bins
        new_bin_penalty += 15.0 * progress;

        score = new_bin_penalty;
    } else {
        // Penalize using an existing bin if it's the only one that fits, 
        // but it leaves a very poor residual (a "wasteful" fit).
        if fitting_bins_count == 1 && post_residual < 15 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Best-Fit (minimize post_residual)
    // We penalize high post_residual quadratically to favor tight packing.
    let mut score = post * post;

    // Lookahead coupling: If next item is large, prioritize leaving enough space.
    // If next_item_size > post_residual, we create a "future-proof" penalty.
    if next_item_size > 0 {
        if (next_item_size as f64) > post {
            score += (next_item_size as f64 - post).powi(2) * 0.5;
        }
    }

    // Dynamic thresholding: As we approach the end of the stream, 
    // become more aggressive in packing into existing bins (penalize opening new ones).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Exponential penalty for opening new bins as the stream progresses.
        // This forces the algorithm to exhaust open bins before creating new ones.
        score += 1000.0 * (1.0 + progress.powi(3));

        // If there are other bins that could fit this, penalize the new bin heavily.
        if fitting_bins_count > 0 {
            score += 5000.0;
        }
    } else {
        // Reward bins that have residuals close to the mean_residual to maintain uniformity,
        // which helps in keeping future items fitting into a variety of bins.
        let deviation = (post - mean_residual).abs();
        score -= deviation * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Harmonic classes logic: prioritize bins that leave residuals which are multiples of common item sizes.
    // The objective is to minimize the score, so we penalize 'bad' residuals (those that leave unusable gaps).

    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0; // Heavy penalty for opening new bin if existing ones fit
        } else {
            score -= 20.0; // Slight incentive to open a new bin if nothing else fits well
        }
    }

    // 2. Harmonic alignment: Encourage post_residual to be 0 (perfect fit) or a multiple of 20
    // (since items are often 20, 25, 40, 50, etc.)
    let harmonic_penalty = (post_residual % 20) as f64 * 1.5;
    score += harmonic_penalty;

    // 3. Lookahead synergy: If the next item fits into the post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 45.0;
        // Further reward if it creates a near-perfect fit for the next item
        if (post_residual - next_item_size) < 10 {
            score -= 25.0;
        }
    }

    // 4. Density balancing: Penalize bins that deviate significantly from the mean residual
    // to keep bins roughly at the same fill level (avoids creating many "almost empty" bins).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 5. Last-chance logic: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Progression scaling: As we approach the end of the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small "dead" gaps (1..9) 
    // that are unlikely to accommodate future items, while accounting for global bin pressure.

    let mut score = post_residual as f64;

    // Penalty for creating a "dead" gap: if the remaining space is too small 
    // to fit the smallest possible item (assumed 10) or the next incoming item.
    // We prioritize bins where the post_residual is exactly 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: If the next item is large, penalize bins that can't fit it.
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 20.0;
    }

    // Encourage filling existing bins rather than opening new ones unless the 
    // current bin is a very poor fit.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. Penalize it based on how many bins are already open.
        // The more bins open, the higher the cost of opening another.
        score += (open_bins_count as f64) * 15.0;
    } else {
        // If it's an existing bin, reward it if it's the only one that fits the item.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Normalize against mean_residual to prevent bin fragmentation (keeping residual 
    // variance low across bins).
    score += (post_residual as f64 - mean_residual).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base cost: The post_residual (Best Fit principle).
    let mut score = post_residual as f64;

    // 2. Penalize creating a new bin unless absolutely necessary (fitting_bins_count is 0).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 500.0;
    }

    // 3. Lookahead optimization: If we have a next item, we want to minimize the gap
    // created by the current item so that the next item fits perfectly.
    // If post_residual is very close to next_item_size, we reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward configurations where the next item fits perfectly or leaves minimal waste
            let waste_after_next = (post_residual - next_item_size) as f64;
            score -= (100.0 - waste_after_next) * 0.5;
        } else {
            // Penalize placements that make the next item definitely require a new bin
            score += 20.0;
        }
    }

    // 4. Balance current bin usage against the global mean residual.
    // If our current post_residual is significantly worse than the mean, penalize.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // 5. Dynamic pressure: As we approach the end of the stream, prioritize tightest fits
    // to avoid leaving too many bins with small residuals.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight (standard Best-Fit logic)
    // We already initialized score = post_residual.

    // 2. Lookahead Synergy: If the next item fits into the post_residual space, reward this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 45.0 * (1.0 - progress * 0.5); 
    }

    // 3. Fragmentation Penalty: Penalize small, unusable remainders (e.g., < 10) unless they are 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Global State Awareness: If we have many open bins, penalize opening a new one.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // High penalty for new bins if we have plenty of open space elsewhere.
        score += 30.0 + (open_bins_count as f64 * 2.0);

        // If we are nearing the end of the stream, be more conservative with new bins.
        if progress > 0.8 {
            score += 40.0;
        }
    } else {
        // Reward bins that are closer to the mean_residual to keep bin distribution uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 5. Scarcity Logic: If this is the last bin that can fit the item, prioritize it to avoid 
    // forcing a new bin later.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // 6. Extreme Fit Bonus: Perfect fills are excellent.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening a new bin early in the stream, but allow it if it's the only option.
    // We want to force Best-Fit behavior by heavily penalizing large post_residuals (slack).
    let mut score = post * post;

    // Favor bins that leave just enough space for the next item (lookahead coupling)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (100.0 - (post - next_item_size as f64).abs()) * 0.5;
    }

    // Adjust for bin scarcity: if few bins fit the item, prioritize using one of them 
    // to avoid the penalty of opening a brand new bin.
    if bin_residual < bin_capacity && fitting_bins_count > 0 {
