    }

    // Penalize bins that deviate significantly from the mean residual to keep packing density uniform
    let residual_penalty = (post - mean_residual).abs() * 10.0;
    score += residual_penalty;

    // If this is a new bin (residual == capacity), add a high base cost that decays 
    // as the stream progresses, reflecting the need to pack tighter at the end.
    if bin_residual == bin_capacity {
        score += 2500.0 * (1.0 - progress * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but not zero (fragmentation)
    // We favor "Perfect Fit" (residual 0) or leaving enough room for a future item.
    if post_residual > 0 {
        score += (bin_capacity as f64 / (post_residual as f64 + 1.0)).powf(1.5);
    }

    // 2. Lookahead Coupling: If next_item_size is known, penalize bin choice if it prevents 
    // a potential perfect match for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // This bin cannot fit the next item; penalize proportional to the wasted capacity
            score += 25.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
