    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Density Balancing: If we have many open bins, penalize opening a new one (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // 4. Harmonic Modulo Logic: Favor placements that leave residuals which are common multiples of item sizes.
    // This helps align future items into the remaining space.
    if post_residual > 0 {
        score += (post_residual % 10) as f64 * 0.5;
    }

    // 5. Scarcity Adjustment: If only one bin fits the item, it is a high-priority bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Progress-based Pressure: As the stream nears the end, become more aggressive about 
    // packing tightly to avoid opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
