    };

    // Penalize opening a new bin (bin_residual == bin_capacity).
    // The cost of a new bin is weighted by how many existing bins can already fit the item,
    // effectively discouraging new bin creation if current bins are viable.
    let new_bin_penalty = if bin_residual == bin_capacity {
