    // 1. Dead Space Penalty: Penalize residuals that are too small to fit typical future items (e.g., < 10)
    // but large enough to be "wasted" space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item can fit in the post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Global Pressure: Discourage opening new bins unless the fit is extremely tight (Best Fit behavior).
    // If this is a new bin (bin_residual == bin_capacity), apply a penalty based on how many bins are open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
        // If there are other bins that could have fit the item, penalize opening a new one heavily.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Mean Residual Balancing: Favor bins that keep the overall mean residual consistent.
    // This prevents creating many bins with very low residuals while others remain empty.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Progress Normalization: As we approach the end of the stream, prioritize closing bins
    // by preferring smaller post_residuals (already reflected in base score).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post_residuals (dead space)
    score += (post_residual as f64) * 0.5;

    // 2. Lookahead optimization: If post_residual perfectly matches next_item, heavily reward it
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // 3. Lookahead penalty: If post_residual is slightly smaller than next_item_size, it's a "bad" fit
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 40.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
    }

    // 4. Global balance: If this is a new bin, only open if it's really necessary
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is higher if we have many bins or few items left
        let progress = step_index as f64 / total_items as f64;
        score += 35.0 + (progress * 20.0) + (open_bins_count as f64 * 0.5);
    } else {
        // 5. Mean residual alignment: Favor bins that stay close to the average state
        let diff_from_mean = (post_residual as f64 - mean_residual).abs();
        score += diff_from_mean * 0.1;

        // 6. Last-chance logic: If this is the only bin that fits, prioritize it
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Penalize leaving small, unusable slivers.
    // If post_residual is < 10 (common minimum size), it is likely to become 'dead space'.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead Integration: If next_item_size is large, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Strong incentive to keep space for the next item
        } else if post_residual > 0 {
            score += 15.0; // Penalty if current placement blocks the next item
        }
    }

    // 3. Global Efficiency: Balance against mean_residual to prevent fragmentation.
    // If we are significantly above the mean, we are likely wasting space.
    if (post_residual as f64) > mean_residual {
        score += 10.0 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // 4. Thresholding New Bins: Only open a new bin if the current fit is extremely poor
    // or if we are nearing the end of the stream (where consolidation matters less).
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high.
        score = 60.0 + (progress * 20.0);

        // If we are forced to open a new bin because no fit is good, reduce the penalty.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Encourage filling bins that are already partially filled (lower residual).
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best Fit (minimize post_residual)
    let mut score = post;

    // Penalty for creating "fragmented" space (small, unusable residuals)
    // We heavily penalize residuals that are too small to fit common items (below 10)
    // but only if we are not opening a new bin.
    if bin_residual != bin_capacity && post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 + progress);
    }

    // Lookahead logic: if next_item_size is large, favor larger residuals in current bin
    // to preserve space for smaller items in other bins, or vice-versa.
    if next_item_size > 0 {
        let diff = (post - next_item_size as f64).abs();
        score += diff * 0.5 * (1.0 - progress);
    }

    // New bin avoidance: If a new bin is being considered (bin_residual == bin_capacity),
    // apply a significant penalty to force filling existing bins first, 
    // unless the current fit is extremely poor.
    if bin_residual == bin_capacity {
        // The "New Bin" cost: higher late in the stream to consolidate packing
        score += 45.0 + (30.0 * progress);

        // If we have many open bins, penalize opening another one
        score += open_bins_count as f64 * 2.0;
    } else {
        // If this is the last fitting bin, reward it to avoid opening a new one
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Interaction between mean_residual and current fit
    // Penalize bins that deviate significantly from the mean efficiency
    score += (post - mean_residual).powi(2) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize configurations that leave small, unusable gaps.
    // If post_residual is very small (< 10), it often becomes "dead space" that cannot fit any item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2. Harmonic Lookahead Coupling:
    // If the next item is large, prioritize bins that can accommodate it.
    // We treat the residual as a modular resource.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that have enough space for the next item.
            score -= 15.0;
        } else {
            // Penalize bins that will definitely force a new bin for the next item.
            score += 5.0;
        }
    }

    // 3. Density Balancing:
    // Avoid creating bins with extremely low residuals if we have many bins open,
    // as this fragments the remaining capacity.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 10.0;
    }

    // 4. New Bin Threshold:
    // Discourage opening a new bin unless the current fit is extremely poor.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless all other options are exhausted or extremely inefficient.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if the current fit is truly terrible (e.g., > 60 wasted space)
            score += 65.0;
        } else {
            // No other choice
            score -= 50.0;
        }
    }

    // 5. Progression Scaling:
    // As the stream nears the end, prioritize tightly packing remaining items.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize "sliver" residuals (1-9)
    // which are unlikely to be filled by subsequent items.

    let mut score = post_residual as f64;

    // Penalty for creating unusable dead space (1..9 are notoriously hard to fill)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Heuristic: If we have many open bins, penalize opening a new one significantly
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 15.0;
    }

    // Lookahead: If next_item_size is large, favor bins that have enough space left 
    // to accommodate it, effectively reducing the "cost" of those bins.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // If this is the only fitting bin, prioritize it to avoid wasting a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Adaptive pressure: As the stream nears the end, penalize unused capacity more aggressively
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Prioritize Best-Fit: Lower post_residual is generally better (standard BFD logic)
    // 2. Penalize opening new bins unless necessary
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0; // Heavy penalty for opening a new bin if space exists
        } else {
            score -= 50.0;  // Incentive to open a new bin if it's the only choice
        }
    }

    // 3. Lookahead Matching (Aggressive):
    // Reward bins where the post_residual matches the next item size perfectly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Penalize leaving a gap slightly larger than the next item
            score += (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Penalize bins that will definitely not fit the next item
            score += 20.0;
        }
    }

    // 4. Mean Residual Balancing:
    // Avoid creating bins that are significantly tighter than the current average
    // This helps maintain a "cushion" for larger items later in the stream
    if (post_residual as f64) < (mean_residual * 0.5) {
        score += 10.0;
    }

    // 5. Progress-based refinement
    // As we approach the end of the stream, prioritize tight fits to close bins
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual: 0 is perfect, 100 is empty.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: Favor tightest fit (Best Fit logic)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // Only open a new bin if the alternative fits are extremely poor (dead space)
    if is_new_bin {
        if open_bins_count == 0 {
            return 0.0;
        }
        // Penalize opening a new bin heavily unless we are late in the stream
        // or the average residual is already quite high (meaning existing bins are fragmented)
        score = 25.0 + (mean_residual * 0.5) - (progress * 15.0);
    } else {
        // Lookahead heuristic: If next_item_size fits in the post_residual,
        // prioritize this bin to preserve future capacity.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }

        // Penalty for leaving "orphan" space that is too small for common items (e.g., < 10)
        if post_residual < 10 && post_residual > 0 {
            score += 20.0;
        }

        // If this is the only bin that fits, we are constrained.
        // We favor using it if the post_residual isn't terrible.
        if fitting_bins_count == 1 && post_residual < 20 {
            score -= 10.0;
        }
    }

    // Adjust score based on global bin density
    // If mean_residual is low, we are packing well; keep it tight.
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: punish large post-residuals to favor Best-Fit behavior.
    // Squaring the post_residual creates a non-linear preference for tighter fits.
    let mut score = (post_residual as f64).powf(2.0);

    // Penalty for opening a new bin: significantly increase the score of empty bins 
    // to prevent premature bin creation, but scale this penalty by progress.
    // In early stages, we are more conservative; in late stages, we are more aggressive.
    if is_new_bin {
        score += (bin_capacity as f64).powf(1.8) * (1.5 - progress);
    }

    // Lookahead logic: if we know the next item, penalize current placements that 
    // leave a post_residual too small to accommodate the next item (creating "dead" slivers).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size as f64 - post_residual as f64).powf(1.5);
    }

    // Heuristic coupling: If the bin is the last chance for the current item, 
    // reduce the penalty to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // Dynamic adjustment based on mean_residual: if current bins are generally empty,
    // favor bins that are already partially filled (lower mean_residual is better).
    score += (mean_residual * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Harmonic classes logic.
    // Goal: Minimize fragmentation by preferring "tight" fits (low post_residual) 
    // while biasing against leaving small, unusable slivers (< 10).

    let mut score = post_residual as f64;

    // 1. Penalty for creating "Dead Space" (slivers < 10 are rarely useful)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // 2. Harmonic Class Alignment: Favor bins where the post_residual is a multiple of 
    // common item size classes (e.g., 20, 25, 33) to maximize future compatibility.
    let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_penalty * 0.5;

    // 3. Lookahead Logic: If the next item fits into the current post_residual,
    // strongly incentivize this bin to preserve bin density.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 4. Scarcity Constraint: If this is the only fitting bin, lower the threshold 
    // for accepting a "bad" fit to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // 5. Global Capacity Pressure: As the stream progresses, prioritize filling 
    // existing bins more aggressively to consolidate space.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64 * 2.0);

    // 6. New Bin Threshold: If bin_residual == bin_capacity, we are evaluating a new bin.
    // We only want to open a new bin if the current "best" fit is extremely poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high.
        score = 85.0 - (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

