    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (residual == capacity), add a penalty proportional to current open bins.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 2.5);
    }

    // 4. Tightness Calibration: Favor bins that leave a residual close to the mean_residual
    // of all open bins to maintain a balanced packing density.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Last Chance Logic: If this is the only bin that can fit the item, 
    // provide a strong incentive to take it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Progress Scaling: As we approach the end of the stream, 
    // become more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger post_residuals.
    // We prefer the smallest post_residual (Best Fit).
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead mechanism: 
    // If the post_residual is close to the next_item_size, we reward this bin.
    // We want to minimize the delta between the remaining space and the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score -= 50.0 / (1.0 + diff);
    }

    // 3. Penalty for opening new bins:
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless no existing bins can fit the item or the mean residual is very poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 65.0; // Strong penalty to avoid fragmentation
        }
        // If our mean residual is already quite low, opening a new bin is less harmful.
        score += mean_residual * 0.5;
    }

    // 4. Tight fit incentive:
    // If this bin is the last chance for the current item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Progression adjustment: 
    // As we approach the end of the stream, prioritize closing bins to reduce waste.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

