    // Best-fit principle: smaller post_residual is better.
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' (bins that are too small to fit the next item)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // Dynamic thresholding: If we are near the end of the stream, prioritize closing bins
    // over creating new ones to avoid leaving half-empty bins behind.
    if is_new_bin {
        // High cost to open a new bin early on, but reduces as we approach the end
        score += 35.0 * (1.0 - progress);

        // If we have many open bins that could fit the item, penalize opening a new one
        if fitting_bins_count > 0 {
            score += 50.0 + (fitting_bins_count as f64 * 5.0);
        }
    } else {
        // Heuristic to balance bin usage: favor bins that are already closer to the mean residual
        // This keeps the "fill levels" of open bins somewhat synchronized.
        let residual_deviation = (bin_residual as f64 - mean_residual).abs();
        score += residual_deviation * 0.15;

        // If this bin is the last chance for this specific item, give it a slight priority boost
        if fitting_bins_count == 1 {
            score -= 5.0;
        }
    }

    // Final adjustment: penalize bins that are left with very small, unusable slivers
    // (e.g., leaving 1-9 space is often worse than leaving 0)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
