    let mut score = post;

    // Favor filling bins that are already "tight" to keep open_bins_count low.
    // As progress increases, we become more desperate to fit items into existing bins.
    let tightness_penalty = (mean_residual - post) * progress;
    score += tightness_penalty;

    // Penalize opening a new bin (bin_residual == bin_capacity)
    // The penalty grows as we progress through the stream.
    if bin_residual == bin_capacity {
        score += 40.0 + (progress * 60.0);
    }

    // Lookahead logic: if next_item_size is large, avoid leaving a small post_residual 
    // that creates "unusable" gaps (e.g., leaving 15 space when next is 20).
    if next_item_size > 0 {
        let gap_waste = if post < next_item_size as f64 && post > 0.0 {
            (next_item_size as f64 - post) * 0.5
        } else {
            0.0
        };
        score += gap_waste;
    }

    // Encourage using the last fitting bin if we are near the end of the stream
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
