    // 2. Lookahead Synergy: If next_item_size fits in the post_residual, reward this placement.
    // This reduces fragmentation by creating "niche" bins for upcoming items.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
