    // 3. Harmonic Filling: Favor bins that leave room for common harmonic fractions (e.g., 1/2, 1/3, 1/4 of capacity).
    // Specifically, if post_residual is close to a multiple of 20, reward it to keep bins "alignable".
    let mod_res = post_residual % 20;
    if mod_res < 5 {
        score -= 10.0;
    }

    // 4. Thresholding: If this is the only fitting bin, we must take it unless it's extremely wasteful.
    if fitting_bins_count == 1 && post_residual > 30 {
