    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating a "sliver" (fragmentation)
    // Small residuals are hard to fill; penalize residuals in range [1, 15]
    if post_residual > 0 && post_residual < 16 {
        score += (16.0 - post_residual as f64) * 2.5;
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // significantly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // Dynamic adaptation: As the stream progresses, prioritize closing bins
    // to minimize open_bins_count. If we are near the end, be more aggressive.
    let density_penalty = (open_bins_count as f64 / 10.0) * progress;
    score += density_penalty * 5.0;

    // Handle the "new bin" candidate (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is already very tight
        // or if we have very few fitting bins, to avoid premature bin exhaustion.
        if fitting_bins_count > 0 {
            // Apply a heavy penalty to opening a new bin if existing bins can fit the item
            score += 40.0 + (progress * 20.0);
        } else {
            // If no existing bin can fit, opening a new bin is mandatory; keep base score low
            score -= 10.0;
        }
    } else {
        // Favor bins that bring the residual closer to the global mean_residual
        // This keeps bin occupancy balanced across the set.
        let balance_factor = (post_residual as f64 - mean_residual).abs();
        score += balance_factor * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize post_residuals that leave small, unusable gaps.
    // Small gaps (1-9) are often "dead space". We penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the current post_residual,
    // we reward this placement significantly to prioritize tight packing.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Fragmentation Control: If this is the only bin that fits the current item,
    // we should prioritize using it to keep open_bins_count low, unless the fit is atrocious.
    if fitting_bins_count == 1 && post_residual > 5 {
        score -= 20.0;
    }

    // 4. Distribution Balancing: Bias towards keeping the mean_residual stable.
    // If our post_residual is significantly lower than the global mean, we are "tightening"
    // the bin, which is usually good.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. New Bin Thresholding: If bin_residual == bin_capacity (New Bin),
    // we add a significant constant penalty to ensure we only open a new bin if 
    // existing bins are truly poor fits (high post_residual).
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    // 6. Progress Scaling: As we approach the end of the stream, prioritize
    // closing bins (lower post_residual) to avoid leaving many half-empty bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the remaining space is too small to fit any likely future items (e.g., < 10),
    // we penalize it heavily to force packing into larger gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead optimization: If next_item_size is large and won't fit in post_residual,
    // we favor bins that leave enough room for that specific item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open bins pressure: If this is an empty bin (bin_residual == bin_capacity), 
    // only choose it if the penalty for using existing bins is high.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the fitting is poor.
        score = 40.0 + (open_bins_count as f64 * 0.5);
    } else {
        // 4. Tightness reward: Favor bins where the item fits perfectly or fills most of the space.
        // We subtract a portion of the filled space to reward high-density packing.
        score -= (bin_capacity - post_residual) as f64 * 0.2;
    }

    // 5. Global state normalization: As we approach the end of the stream, 
    // prioritize closing open bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 100.0; 
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
