        }
        // If the item is large, reduce the penalty for a new bin.
        score -= (item_size as f64 * 0.4);
    }

    // 5. Global Efficiency: 
    // If we are late in the stream, prioritize aggressive packing.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - (post_residual as f64 / bin_capacity as f64)) * 10.0;
    }

    // 6. Mean Residual Balancing:
    // Avoid creating bins that are significantly below the current mean residual.
    if (post_residual as f64) < (mean_residual * 0.5) {
