    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space; we want to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for creating a "fragmented" bin: if the residual is small (e.g., < 10) 
    // but not zero, it's often wasted space.
    if post > 0.0 && post < 15.0 {
        score += (15.0 - post) * 2.0;
    }

    // Lookahead logic: if the next item could fit into the current post_residual, 
    // reward this bin heavily.
    if next_item_size > 0 && post >= next_item_size as f64 {
        score -= (next_item_size as f64) * 0.5;
    }

    // Dynamic thresholding: As the stream progresses, become more aggressive about 
    // filling existing bins (penalize opening new bins) to avoid bloat.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // As we reach the end of the stream, the cost of opening a new bin increases 
        // exponentially to force consolidation.
        score += 20.0 + (progress * 50.0);
    } else {
        // If the bin is already open, favor bins that have a residual close to the 
        // global mean to keep bin usage uniform.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.1;
    }

    // If this is the only bin that can fit the item, give it a significant priority boost
    // to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best-Fit (minimize post_residual). 
    // If we are choosing a new bin (bin_residual == bin_capacity), penalize it 
    // to force usage of existing bins unless the fit is extremely poor.
    if bin_residual == bin_capacity {
        score += 25.0; 
    }

    // 2. Harmonic Class Logic: Reward placements that leave post_residual 
    // as a multiple of common item sizes or small divisors of capacity.
    // This helps "align" bins to future incoming items.
    let harmonic_penalty = (post_residual % 20) as f64 * 0.5;
    score += harmonic_penalty;

    // 3. Lookahead Logic: If the next item fits into the current post_residual,
    // we significantly reward this placement (Best-Fit-Decreasing heuristic variant).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 4. Density Balancing: If we have many open bins, penalize creating a new one
    // or picking a bin that leaves a large, unusable gap (dead space).
    if open_bins_count > 0 {
        let density_factor = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= density_factor * 10.0;
    }

    // 5. Last Chance Heuristic: If this is the only bin that can fit the current item,
    // we must take it to avoid wasting a new bin, unless the fit is catastrophic.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progression scaling: As we approach the end of the stream, 
    // prioritize tighter packing to minimize final bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // We heavily penalize post_residual values in the (0, 10) range as they are effectively unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 1.0);
    }

    // Encourage Best-Fit behavior: prioritize bins where the resulting residual is minimal.
    // This is the baseline score.

    // If this is a new bin (bin_residual == bin_capacity):
    // Heavily penalize opening a new bin unless the existing options are extremely poor.
    if bin_residual == bin_capacity {
        score += 25.0;
