    // We use a quadratic penalty for small residuals to encourage "Best Fit" behavior.
    let gap_penalty = if post_residual < 10 && post_residual > 0 {
        (10.0 - post_res).powi(2) * 2.0
    } else {
        0.0
    };

    // Lookahead logic: if next_item_size is large, favor bins that have enough space
    // to accommodate it (Best Fit Decreasing style).
    let lookahead_score = if next_item_size > 0 {
        if post_residual >= next_item_size {
            -15.0 * (1.0 - progress) // Reward creating space for the next item
        } else {
            10.0 * progress // Penalize blocking the next item
        }
    } else {
        0.0
    };

    // Global state awareness:
    // If we have many open bins, prioritize filling them tightly to reduce count.
    // If few bins, be more permissive to avoid opening new ones.
    let consolidation_score = (open_bins_count as f64) * (post_res / 100.0);

    // New bin candidate handling:
