    // 4. Density Balancing: If we have many open bins, prioritize packing 
    // tightly into existing bins to reduce open_bins_count.
    if open_bins_count > 0 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. New Bin Threshold: If fitting_bins_count is 1, this is the only 
    // bin that can take the item. We should reward it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Distributional Smoothing: Adjust based on the mean residual.
    // If the current bin is significantly emptier than the average, 
    // it's a good candidate to receive larger items.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // 7. Progression Scaling: As we reach the end of the stream, 
    // prioritize closing bins even at the cost of slight inefficiency.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
