    // 4. Global Load Balancing: Avoid opening new bins if open bins are under-utilized
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if open_bins_count > 0 {
            // Penalize opening new bin if current average residual is high (implies fragmentation)
            score += mean_residual * 0.8;
