        // Penalize opening a new bin if we are early in the stream
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 20.0;
    }

    // 5. Last chance mitigation: If this is the only bin that fits, prioritize it heavily
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // 6. Prefer bins that keep residuals close to the global mean to avoid outlier gaps
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
