    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // 4. New Bin Logic: Discourage opening new bins unless the fit is extremely tight (Best Fit behavior).
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if existing ones can fit the item.
            score += 100.0 * (1.0 - progress);
        } else {
            // Base cost for opening a new bin is the residual space it creates.
            score = post_residual as f64;
        }
    } else {
