}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit principle)
    // We add a penalty for "wasted" potential based on the next item size (lookahead)
    // If the next item fits into the post_residual, we reward this bin.
    let lookahead_penalty = if next_item_size > 0 && post_residual >= next_item_size {
        -20.0 * (next_item_size as f64 / 100.0)
    } else if next_item_size > 0 {
        10.0 * (next_item_size as f64 / (post + 1.0))
    } else {
        0.0
    };

    // Penalty for opening a new bin when existing bins can fit the item
    let new_bin_penalty = if bin_residual == bin_capacity && fitting_bins_count > 0 {
        150.0 * (1.0 - progress.powi(2))
    } else {
