    let stability_term = (post - mean_residual).abs() * progress;

    // Non-linear coupling: Exponential weight on post_residual to favor tight packing
    // but tempered by the fitting_bins_count to prioritize using last-chance bins.
    let tight_fit_bonus = if fitting_bins_count == 1 { -50.0 } else { 0.0 };

    let score = post + lookahead_penalty + new_bin_penalty + stability_term + tight_fit_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
