    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space after placement (lower is better, i.e., Best Fit).
    let mut score = post_res;

    // Penalty for leaving a very small, unusable gap (fragmentation).
    // If post_residual is between 1 and 9, it's likely "dead space".
    if post_res > 0.0 && post_res < 10.0 {
        score += (10.0 - post_res) * 5.0;
    }

    // Lookahead logic: If the next item could fit in this bin, prioritize this bin.
    if next_item_size > 0 && (post_res >= next_item_size as f64) {
        score -= (next_item_size as f64) * 0.8;
    }

    // Dynamic adaptation: As the stream progresses, favor tighter packing 
    // to avoid leaving too many bins partially full at the end.
    let density_pressure = (open_bins_count as f64 / (step_index as f64 + 1.0)) * 100.0;
    score += density_pressure * progress;

    // Discourage opening a new bin unless the current residual is significantly suboptimal.
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a new bin.
    if bin_residual == bin_capacity {
        // High penalty to open new bin unless previous bins are very full.
        score += 45.0 + (mean_residual * 0.5);
    } else {
        // Reward bins that have high occupancy relative to the mean.
        if (bin_capacity - bin_residual) < (bin_capacity as f64 - mean_residual) as u32 {
            score += 5.0;
