            score += 150.0 + (50.0 * (1.0 - progress));
        } else {
            // Neutral score for opening a new bin when forced
            score = 50.0;
        }
    } else {
        // Lookahead heuristic: If the next item fits into the current post_residual,
        // prioritize this bin to maximize packing density.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }

        // Avoid "fragmentation": Penalize post_residuals that are too small to be useful
        // but too large to be considered "filled" (the "dead zone" 1..10)
        if post_residual > 0 && post_residual < 12 {
            score += 40.0;
        }

        // Global state awareness: If we have many open bins, prioritize filling the 
        // one with the smallest residual (Best Fit) to close it faster.
        if mean_residual < 20.0 {
            score -= 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Dynamic horizon: As we approach the end of the stream, prioritize aggressive 
    // filling of existing bins to reduce total count.
    if progress > 0.8 {
        score -= (1.0 - (post_residual as f64 / bin_capacity as f64)) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
