        score += 30.0 + (50.0 * progress);

        // If we have many bins open, penalize opening another one.
        score += (open_bins_count as f64).powf(1.5);
    } else {
        // If it's an existing bin, favor those that bring the bin closer to mean_residual
        // to keep bin fullness uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += 0.2 * deviation;
    }

    // If this is the last chance for this item to fit into an existing bin,
    // reduce the penalty for a poor fit (Best Fit is better than opening a new bin).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

