    // 4. Mean Residual Balancing: Avoid bins that deviate significantly from the average state.
    // This helps keep bins packed with similar density.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.15;

    // 5. New Bin Logic: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty.
    if bin_residual == bin_capacity {
