        // 4. Penalize bins that are becoming "orphaned" (very low residual)
        // unless they are the only ones left that can fit the item.
        if post_residual < 10 && fitting_bins_count > 1 {
            score += 300.0;
        }
    }

    // 5. Coupling with mean_residual: 
    // Discourage placing items in bins that are significantly emptier than the average,
    // to preserve capacity in those bins for potentially larger future items.
    let residual_deviation = (bin_residual as f64 - mean_residual).abs();
    score += residual_deviation * 2.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit: Penalize large post_residuals (standard Best-Fit logic)
    // 2. Harmonic Class logic: If post_residual is small, it creates "dead space" that cannot fit 
    //    small items (e.g., < 10). We reward placements that leave space for common item sizes.
    let is_empty = bin_residual == bin_capacity;

    if !is_empty {
        // Penalty for creating a "sliver" (space too small for most items)
        if post_residual < 10 {
            score += 50.0;
        }

        // Lookahead: If next item fits in the post_residual, strongly reward this bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }

        // Harmonic alignment: Reward residuals that are multiples of common item sizes (e.g., 20, 25)
        // This keeps the bin "open" for standard item distributions.
        if post_residual % 20 == 0 {
            score -= 10.0;
        }
    } else {
        // New bin penalty: Only open a new bin if the mean residual of current bins is high,
        // suggesting that current bins are already too crowded to accept future items.
        score = 85.0 + (mean_residual * 0.5);
    }

    // Progression scaling: As we approach the end of the stream, prioritize closing bins
    // to minimize the impact of the final bin count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && !is_empty {
        score -= 20.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Avoid opening new bins if there are still fitting bins available
    if is_empty && fitting_bins_count > 0 {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

