        // As the stream progresses, we become more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += (open_bins_count as f64 * 5.0) + (1.0 - progress) * 20.0;

        // Penalize opening a new bin if an existing bin could have fit the item snugly.
        if fitting_bins_count > 0 {
