    // 3. Global State: If we are late in the stream, be more aggressive about 
    // closing bins (lower score for tight fits) to minimize total bin count.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // 4. New-Bin Thresholding: Prevent opening a new bin unless the current 
    // fitting options are extremely poor (i.e., they create large dead space).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other options exist
            score += 65.0 + (mean_residual * 0.5);
        } else {
            score -= 10.0; // Must open a new bin
        }
    }

    // 5. Density heuristic: If a bin is nearly full, prioritize it to finalize it.
    if post_residual < 5 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
