    // Penalize large gaps that are too small to fit common items (e.g., < 10).
    let mut score = post * (1.0 + 0.5 * (10.0 / (post + 1.0)));

    // Lookahead coupling: If next_item_size exists, penalize bins that cannot fit it.
    if next_item_size > 0 {
