    // 5. Mean-Residual Alignment: Prefer bins that stay close to the average state of the system 
    // to prevent creating extreme outliers in bin fullness.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.2;

    // 6. Progression Phase: As the stream nears the end, be more aggressive about closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating "dead zones" (small residuals that likely won't fit future items)
    // We penalize residuals between 1 and 9 heavily, as most items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // reward this bin to prioritize packing pairs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // Global state awareness: If we have many open bins, prioritize tightening existing ones.
    // If we have very few, be more conservative about opening a new bin.
    if bin_residual == bin_capacity {
        // This is a candidate for a NEW bin. 
        // Only open if we are forced to (fitting_bins_count == 0) or if we are 
        // nearing the end of the stream and need to clear out.
        if fitting_bins_count > 0 {
            score += 45.0 + (open_bins_count as f64 * 2.0);
        } else {
            score -= 10.0; // Forced to open
        }
    } else {
        // If this bin is a "tight fit" (post_residual is small), reward it.
        if post_residual < 15 {
            score -= 15.0;
        }

        // Dynamic horizon: As the stream progresses, prioritize finishing bins
        // to reduce the total count of open bins.
        score += (progress * 10.0);
    }

    // Balance against the mean residual to prevent fragmentation.
    if post_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating a bin that is too empty to be useful later in the stream.
    // If post_residual is high, we penalize it more as we approach the end of the stream.
    score += post * progress * 0.5;

    // If this is the only bin that can fit the item, strongly prioritize it to avoid
    // opening a new bin unnecessarily (Best Fit constraint).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead logic: if the next item is large, favor bins that leave enough space
    // to potentially fit that next item, or avoid bins that leave just a tiny fragment.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            // Good: can fit the next item, reward this bin.
            score -= (next * 0.8) / (1.0 + post - next);
        } else if post > 0.0 && post < 10.0 {
            // Bad: creates a "sliver" that is likely unusable, penalize.
            score += 20.0 / post;
        }
    }

    // If considering a new bin, penalize based on how many bins are already open 
    // to discourage fragmentation, unless the current open bins are very full.
    if bin_residual == bin_capacity {
        let avg_load_factor = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        // Only open new bin if existing bins are significantly crowded.
        score += (open_bins_count as f64 * 2.0) * (1.0 - avg_load_factor);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals to favor tight packing.
    // We use a quadratic penalty to discourage leaving large "dead" gaps.
    score += (post_residual as f64).powi(2) * 0.05;

    // 2. Harmonic Lookahead: If next_item_size fits in post_residual, reward this bin.
    // This is the core "Harmonic Class" logic: grouping items that fit together.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Fragmentation Mitigation: Penalize bins that leave tiny, unusable residuals.
    // If post_residual is < 10 (the minimum item size), it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 4. New-Bin Thresholding: Only open a new bin if the current fit is catastrophic.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy "cost"
    // that decreases as the total bin count increases (to force consolidation).
    if bin_residual == bin_capacity {
        score += 45.0 - (open_bins_count as f64 * 0.1);
    }

    // 5. Fitting Constraint: If this is the only bin that fits, prioritize it heavily
    // to prevent unnecessary bin proliferation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // 6. Distributional Balance: Use mean_residual to avoid uneven bin filling.
    // Favor bins that are closer to the current mean to maintain uniform density.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual values that fall into the "unusable" range (1..10).
    // Small gaps are the primary cause of poor bin utilization in 1D packing.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits in the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: If we are forced to open a new bin, penalize the new bin heavily
    // unless the current open bins are already very full (high mean_residual means low utilization).
    if bin_residual == bin_capacity {
        // Higher open_bins_count increases the penalty for opening a redundant new bin.
        score += (open_bins_count as f64) * 15.0;

        // If we have many fitting bins, opening a new one is almost always suboptimal.
        score += (fitting_bins_count as f64) * 40.0;
    } else {
        // 4. Tightness Reward: Favor bins that become very tight (e.g., post_residual near 0).
        // This is the Best-Fit principle.
        score -= (100.0 - post_residual as f64) * 0.2;
    }

    // 5. Stream Progression: As we approach the end of the stream, prioritize closing bins
    // by being more aggressive with fitting items into existing capacity.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (open_bins_count as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
