    }

    // 4. Mean-residual balancing:
    // Avoid creating bins that are significantly "emptier" than the current average.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // 5. New-bin thresholding:
    // If the bin is new, make the score high to discourage opening new bins unless necessary.
    if bin_residual == bin_capacity {
        score += 45.0; 
        // If we are near the end of the stream, increase penalty for new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
