    // Dynamic threshold: As we progress, prioritize packing tightly.
    // If few bins are open, we are more tolerant of opening a new bin if the fit is poor.
    if is_new_bin {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Penalize opening a new bin if there are fitting bins available.
            // The penalty increases as we approach the end of the stream.
            score = 30.0 + (progress * 40.0);
        }
    } else {
        // Reward placements that bring the bin residual closer to the global mean,
        // promoting uniform bin usage.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;

        // If this is the only bin that can fit the item, prioritize it heavily.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space after placement (Best Fit principle).
    // Lower residual is generally better (tighter packing).
    let mut score = post;

    // Penalty for creating a "fragmented" bin:
    // If post_residual is small (e.g., < 10), it's often unusable for future items.
    // We penalize very small residuals exponentially to favor slightly larger, more flexible gaps.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powi(2) * 5.0;
    }

    // Lookahead logic: If the next item is large, favor bins that leave enough space for it.
    // If post_residual is less than the next item, we penalize the bin proportionally
    // to the lookahead size to encourage keeping that bin open for future items.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Stream progression coupling:
    // Toward the end of the stream (progress -> 1.0), we become more aggressive in
    // filling existing bins to avoid opening new ones.
    // We dampen the penalty for small residuals as the stream concludes.
    let urgency = 1.0 - progress;
    score -= (urgency * post) * 0.5;

    // Favor bins that align with the global mean residual to keep bin states uniform.
    // Deviating from the mean suggests a bin is becoming an outlier.
    let mean_diff = (post - mean_residual).abs();
    score += mean_diff * 0.2;

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy threshold penalty.
    // This forces the algorithm to prefer fitting into existing bins unless the "fit"
    // is exceptionally bad (high post_residual penalty).
    if bin_residual == bin_capacity {
        // The cost of opening a new bin is high, but scales down slightly if 
        // there are very few fitting bins left (scarcity).
        let scarcity_factor = if fitting_bins_count == 0 { 20.0 } else { 50.0 };
        score += scarcity_factor + (progress * 20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
