    let mod_val = post_residual % 25;
    if mod_val == 0 {
        score -= 15.0;
    }

    // 4. Thresholding: If this is the only bin that fits, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
