pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Heuristic Strategy: Best-Fit Decreasing (BFD) foundation with lookahead penalty/reward.

    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin if an existing bin could fit the item.
    // We heavily penalize the "New Bin" candidate unless we are in the early stages 
    // or the current fits are extremely poor.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 150.0 * (1.0 - progress * 0.5);
    }

    // 2. Lookahead optimization:
    // If we have a next item, we want to maximize the chance that (post_residual >= next_item_size).
    // If post_residual is slightly too small for the next item, we penalize it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a bin that cannot fit the immediate successor
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward creating a bin that perfectly accommodates the next item
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 3. Global state balancing:
    // Penalize bins that deviate significantly from the mean residual of open bins.
    // This encourages "leveling" the bins to keep them all equally capable of future items.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 4. Critical thresholding:
    // If this is the last chance to fit the item (fitting_bins_count == 1), 
    // we make this bin extremely attractive to prevent opening a new one unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space. Lower is better (Best Fit).
    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is small but > 0, 
    // it prevents larger items from fitting. We penalize values that are 
    // just below common item size thresholds (10-30 range).
    if post_res > 0.0 && post_res < 20.0 {
        score += (20.0 - post_res) * 2.5;
    }

    // Lookahead logic: If the next item is large, favor bins with more space.
    // If next_item_size is 0 (end of stream), prioritize filling existing bins.
    if next_item_size > 0 {
        let next_item_f = next_item_size as f64;
        if post_res < next_item_f {
            // Penalize bins that will be too small for the next item
            score += (next_item_f - post_res) * 1.5;
        }
    }

    // Dynamic adjustment based on stream progress:
    // Early in the stream, be more conservative (avoid new bins).
    // Late in the stream, favor tight packing (smaller residuals).
    let progress_weight = (1.0 - progress) * 10.0;
    score += progress_weight * (mean_residual - post_res).abs();

    // If this is a brand new bin (bin_residual == bin_capacity), 
    // only choose it if the penalty for fitting into existing bins is extreme.
    if bin_residual == bin_capacity {
        // Higher cost for opening a new bin early on.
        score = 50.0 + (progress * 30.0);

        // If no existing bin can fit the item, reduce the penalty to force opening.
        if fitting_bins_count == 0 {
            score = 0.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residual (Best Fit).
    // Penalize large post_residual to keep bins tight.
