    // 2. Harmonic/Modulo logic: Reward placements that leave a residual 
    // divisible by common item sizes (tending toward 20, 25, 33, 50).
    // This helps "align" the bin for future items.
    let harmonic_penalty = if post_residual > 0 {
        ((post_residual % 20) as f64) * 0.8 + ((post_residual % 25) as f64) * 0.4
    } else {
        -50.0 // Huge reward for perfect fit (post_residual == 0)
    };
    score += harmonic_penalty;

    // 3. Lookahead logic: If the next item can fit in the post_residual, 
    // highly prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 4. New Bin Threshold: Discourage opening a new bin unless the 
