    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual is already quite low,
        // suggesting current bins are mostly full.
        if mean_residual < 25.0 && open_bins_count > 0 {
            score += 150.0; // Heavily penalize opening new bins early
        } else {
            score += 20.0; // Moderate penalty for new bin
        }
    }

    // 5. Scarcity/Fitting logic: If this is the only bin that fits the current item, 
    // don't penalize it too harshly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

