    // We favor bins that leave the least space.
    score += (post_residual as f64).powf(1.1);

    // 2. Harmonic Class Logic: Penalize "Fragmenting" residuals
    // If the remaining space is small, it's often unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Integration: If next_item_size is large, avoid small post_residuals
    // If the next item won't fit in the remaining space, we prioritize larger residuals 
    // only if the current fit is "tight".
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // 4. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy cost
    // unless the number of open bins is very low or fitting_bins_count is 0.
    if bin_residual == bin_capacity {
