    // 5. Mean residual equilibrium:
    // Penalize bins that deviate from the global mean residual to keep bin fill levels balanced.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 6. Final scaling for progression:
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
