    }

    // 4. Global Density Awareness: Penalize creating bins that deviate significantly from the mean
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // 5. Progression Scaling: As the stream nears completion, prioritize closing existing bins (lower residuals)
    let progress = step_index as f64 / total_items as f64;
    score += progress * (bin_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
