            score += lookahead_penalty;
        }
    }

    // Dynamic pressure: As the stream progresses, prioritize closing bins (lower residual)
    // to minimize the open_bins_count.
    score += (open_bins_count as f64) * progress * 2.0;

    // If this is the only bin that fits, reduce the penalty significantly 
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New bin candidate logic: If bin_residual == bin_capacity, this is a "new bin" request.
    // Apply a scaling factor based on the average occupancy to decide if a new bin is better
    // than a very poor fit in an existing bin.
    if bin_residual == bin_capacity {
        score = 45.0 + (mean_residual * 0.2) - (progress * 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Heuristic: Best-Fit Decreasing logic combined with "harmonic packing" penalty.
    // We heavily penalize small fragments (1-9) which are hard to fill later.
    // We reward placements that leave space for the lookahead item.

    let mut score = post_residual as f64;

    // 1. Fragment Penalty: Small residuals are often "dead space" unless they are 0.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2. Harmonic Class Logic: Reward residuals that match common item size multiples (e.g., 20, 25, 50).
    // This creates "bins of specific types" to increase future fit probability.
    let harmonic_match = (post_residual % 25 == 0) as i32;
    score -= (harmonic_match as f64) * 15.0;

    // 3. Lookahead Logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 4. New Bin Threshold: Discourage opening new bins unless the fit is extremely poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Only open new if we have very few bins or the current mean_residual is too tight.
        // Higher threshold for opening new bins as the stream progresses.
        let progress = step_index as f64 / total_items as f64;
        score += 35.0 + (progress * 20.0);
    }

    // 5. Fitting Constraint: If this is the only bin that fits the current item, 
    // it is highly valuable to use it, even if the fit is suboptimal.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // 6. Mean Residual Balancing: Avoid creating bins that are significantly below the average.
    if (post_residual as f64) < mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (gaps smaller than the smallest likely items)
    // Small gaps (1-9) are notoriously difficult to fill in 1D bin packing.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 15.0;
    }

    // Heuristic: If we have a next item, check if the current bin can accommodate it.
    // If the post_residual is too small to fit the next item, we penalize it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Pressure to consolidate: penalize opening new bins when current ones are available.
    // We increase the score of a new bin (where bin_residual == bin_capacity)
    // proportional to the number of current open bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 12.0;
    }

    // Encourage filling bins that are already closer to the mean residual to keep
    // bin states uniform, reducing variance in packing density.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // Last chance logic: If this is the only bin that can fit the item, 
    // significantly reward it to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Progression logic: As the stream nears the end, prioritize tightest fit (Best Fit)
    // to minimize the number of bins opened in the final stage.
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals (wasted space)
    // 2. New-Bin thresholding: only open a new bin if post_residual (which is bin_capacity - item_size)
    //    is significantly better than the best available fit.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin: penalize heavily unless fitting_bins_count is 0
        score = 85.0 + (mean_residual * 0.5);
        if fitting_bins_count == 0 {
            score = 0.0; 
        }
    } else {
        // Evaluate lookahead: if post_residual is close to next_item_size, it's a perfect match
        if next_item_size > 0 {
            let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
            score -= diff * 0.4;
        }

        // Penalize fragmentation: if post_residual is small but > 0, it's a "dead zone"
        if post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }

        // Encourage filling bins that are already "below average" to consolidate space
        if (bin_residual as f64) < mean_residual {
            score -= 15.0;
        }

        // Favor bins that are the "last chance" (fitting_bins_count == 1)
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Decreasing logic: heavily favor bins where post_residual is small
    // (score is already post_residual, so it naturally prefers tighter fits).

    // 2. Lookahead Penalty: If the next item is large, avoid leaving a small, unusable gap.
    // If the next item cannot fit in this post_residual, apply a penalty.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (1.0 - progress);
        }
    }

    // 3. Fragmentation Control: Penalize creation of "slivers" (very small residuals).
    // A residual between 1 and 9 is often "dead space" because min item size is 1.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. Global State Balancing: Use mean_residual to prevent over-packing one bin
    // while leaving others empty. If this bin is much tighter than average, penalize it.
    if (bin_residual as f64) < mean_residual * 0.8 {
        score += 5.0;
    }

    // 5. New Bin Threshold: If this is a new bin (residual == capacity),
    // only choose it if the current best-fit penalty is extremely high.
    if bin_residual == bin_capacity {
        // Base cost to open a new bin is high, but scales down as we run out of bins
        // or if all other fitting options create terrible fragmentation.
        score = 85.0 - (progress * 15.0);

        // If there are other bins that can fit the item, make opening a new one very unattractive
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating tiny, unusable gaps (1-9) that are difficult to fill
    let fragmentation_penalty = if post_residual > 0 && post_residual < 10 {
        15.0 * (1.0 - (post_res / 10.0))
    } else {
        0.0
    };

    // Reward bins that bring the residual closer to the global mean, 
    // encouraging consolidation (Best-Fit variation)
    let consolidation_bonus = (post_res - mean_residual).abs() * 0.5;

    // Lookahead logic: if the next item fits into the current post_residual, 
    // heavily incentivize this bin.
    let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
        -25.0 * (1.0 + progress)
    } else {
        0.0
    };

    // New bin bias: Increase the cost of opening a new bin as the stream progresses,
    // unless the current fit is extremely poor.
    let new_bin_bias = if bin_residual == bin_capacity {
        30.0 + (progress * 40.0)
    } else {
        0.0
    };

    // Capacity utilization: Penalize leaving large empty spaces (wasteful)
    // weighted by how many other bins could have taken this item.
    let waste_penalty = (post_res.powi(2) / bin_capacity as f64) * (1.0 + fitting_bins_count as f64 * 0.2);

    post_res + fragmentation_penalty + consolidation_bonus + lookahead_bonus + new_bin_bias + waste_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

