    // 2. Harmonic/Modulo penalty: Penalize post_residual if it leaves a "sliver" (fragmentation)
    // Small residuals (< 10) are extremely hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - (post_residual as f64);
    }

    // 3. Lookahead Logic: If the next item fits into the post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
