    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Global Balancing: Penalize bins that deviate too far from the mean residual
    // This encourages "leveling" the load across all open bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 6. Progressive Pressure: As we approach the end of the stream, 
    // prioritize tighter packing (smaller post_residual) more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
