    // 1. Best-Fit Penalty: Penalize large remaining space to keep bins tightly packed.
    // Exponentially weight the post_residual to favor tight fits (Best-Fit principle).
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // prioritize this bin to reduce fragmentation.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. New Bin Thresholding: If this is an empty bin (new bin candidate)...
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean residual is already quite low 
        // (meaning existing bins are nearly full) or if we are nearing the end of the stream.
        let openness_penalty = if mean_residual < 20.0 { 15.0 } else { 55.0 };
        score += openness_penalty + (progress * 20.0);
    } else {
        // 4. Scarcity Logic: If this is the only bin that can fit the current item, 
        // give it a massive priority boost to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 100.0;
        }
    }

    // 5. Global Load Balancing: Penalize bins that deviate significantly from the mean residual
    // to keep the filling level uniform across all open bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

