    } else {
        // Non-linear coupling: Favor bins that reach a lower post_residual, 
        // but penalize bins that leave tiny, unusable fragments (< 10).
        if post_residual < 10 && post_residual > 0 {
            score += 25.0 * (1.0 - progress);
        }

        // Lookahead heuristic: If the next item exists, penalize bins that cannot fit it
        // after this item is placed (if we have a high mean_residual, we have flexibility).
        if next_item_size > 0 && post_residual < next_item_size {
            score += (15.0 * (1.0 - mean_residual / bin_capacity as f64));
        }

        // Encourage filling bins that are already "near empty" to consolidate space
        // by penalizing placement in bins that deviate from the mean_residual.
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += 0.2 * deviation;
    }

    // High-pressure adjustment: If only one bin can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (dead space)
    // We prioritize bins that leave very little space (tight fit).
    score += post_residual as f64 * 1.5;

    // 2. Harmonic Class Logic:
    // If post_residual is a multiple of common small item sizes, it is likely to be filled later.
    // We reward residuals that are "friendly" to common item sizes (e.g., 20, 25, 33, 50).
    let harmonic_penalty = if post_residual > 0 {
        let mod_20 = (post_residual % 20) as f64;
        let mod_25 = (post_residual % 25) as f64;
        (mod_20.min(mod_25)) * 0.8
    } else {
        -5.0 // Strong reward for perfect fit
    };
    score += harmonic_penalty;

    // 3. Lookahead Integration:
    // If next_item_size fits in the post_residual, drastically reduce score to favor this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
