        if (post_residual - next_item_size) < 10 {
            score -= 20.0;
        }
    }

    // 4. New Bin Logic:
    // If bin_residual == bin_capacity, this is a candidate for a new bin.
    // Only open a new bin if the current "fitting_bins" are all "bad" (high residual).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Penalize opening a new bin heavily unless the average open bin is nearly full.
            score = 100.0 + (mean_residual * 0.5);
        }
    }

    // 5. Progression Weighting:
    // Toward the end of the stream, be more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
