pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening new bins heavily early on, but allow it if it creates a perfect fit.
    // As progress approaches 1.0, allow more flexibility for new bin creation.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (1.0 - progress) * 45.0 + (if next_item_size > 0 && (post_residual >= next_item_size) { -10.0 } else { 5.0 })
    } else {
        0.0
    };

