    let open_bins_penalty = if !is_new_bin {
        (open_bins_count as f64) * 0.5
    } else {
        -(open_bins_count as f64) * 0.2
    };

    tightness_score + new_bin_penalty + lookahead_penalty + open_bins_penalty
}

