    // We heavily penalize creating a bin that is almost empty.
    score += (post_residual as f64).powf(1.2);

    // 2. Lookahead Synergy: If the post_residual can fit the next item, reward this bin.
    // This is the core "Aggressive 2-step" logic.
    if next_item_size > 0 && post_residual >= next_item_size {
