    // 3. Mean Residual Balancing: Avoid creating bins that deviate significantly
    // from the average residual, as these often lead to fragmentation.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 4. New Bin Logic: If this is an empty bin, only pick it if no other
