pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalty for creating "dead space" (small residuals that are hard to fill)
    // We penalize residuals in the range [1, 9] heavily as they are unlikely to fit any item.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 2. Lookahead optimization: If the next item fits into the current post_residual,
    // we prioritize this bin. If it doesn't, we add a penalty based on the potential waste.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Reward bin that accommodates the next item
        } else {
            score += 15.0; // Moderate penalty for blocking the next item
        }
    }

    // 3. Dynamic New-Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), calculate a dynamic cost
    // to open a new bin based on how full the existing bins are.
    if bin_residual == bin_capacity {
        // If we have many bins with low residuals, opening a new one is inefficient.
        // We add a penalty proportional to the average occupancy of existing bins.
        let avg_fill = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
        score += 40.0 * avg_fill;

        // As we approach the end of the stream, opening new bins becomes increasingly costly.
        score += 30.0 * progress;
    } else {
        // 4. Fitting Pressure:
        // If this is the only bin that can fit the item, we lower its score to ensure it's picked.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
    }

    // 5. Global Load Balancing:
    // Penalize extreme deviations from the mean residual to encourage uniform bin usage.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * residual_diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space remaining after placement.
    // Lower residual (tighter fit) is generally better (Best-Fit principle).
    let mut score = post;

    // Penalty for creating "dead zones" (small residuals that likely won't fit future items).
    // If post_residual is in the range (0, 10), it is highly likely to become unusable.
    if post > 0.0 && post < 10.0 {
