    // Late in the stream, we prioritize minimizing the number of bins.
    let tightness_factor = 1.0 + (progress * 2.0);
    score *= tightness_factor;

    // Penalty for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), add a significant cost
    // that decays as the number of open bins increases (to avoid excessive fragmentation).
    if bin_residual == bin_capacity {
