    // prioritize this bin heavily (negative penalty).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0;
    }

    // 4. Scarcity/Fitting logic: If this is the only bin that fits the current item,
    // we must take it unless the post_residual is catastrophic.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. New Bin Threshold: If considering a new bin, apply a threshold based on 
    // the mean residual of existing bins to prevent premature creation.
    if bin_residual == bin_capacity {
        // High penalty to prevent opening a new bin if an existing one is available
        // unless the mean residual is already quite low (tight packing).
        score += 80.0 + (mean_residual * 0.5);
    }

    // 6. Progressive packing: As the stream nears the end, favor tighter packing 
    // (reduce tolerance for waste).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

