        score -= 25.0;
    }

    // 5. Progression Scaling: As the stream nears completion, become more aggressive 
    // about closing bins (higher penalty for opening new ones).
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // We aim to minimize the score.
    // 1. Base Score: The post-residual space. 
    //    Lower residual means tighter packing, which is generally better.
    let mut score = post_residual as f64;

    // 2. Penalty for creating "dead space":
    //    If the post-residual is small (< 10), it's often unusable for future items (min size 10).
    //    We penalize residuals in the (0, 10) range heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead Logic:
    //    If a next item exists, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can fit the next item after this one.
            score -= 25.0;
        } else {
            // Penalize bins that will definitely not fit the next item.
            score += 10.0;
        }
    }

    // 4. Global State Awareness:
    //    If this is a new bin (bin_residual == bin_capacity), discourage opening it unless necessary.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if other options exist.
        // Scale the penalty by the ratio of current open bins to total items to discourage premature expansion.
        score += 60.0 + (open_bins_count as f64 * 0.5);
    }

    // 5. Efficiency heuristic:
    //    If this is the only bin that fits the item (fitting_bins_count == 1), 
    //    give it a strong bonus to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Distribution awareness:
    //    If the current residual is significantly better than the mean residual,
    //    it suggests this bin is already "tight". We penalize deviating from the mean
    //    to keep bin usage consolidated.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

