    let mut score = post_residual as f64;

    // Penalty for opening new bins: scale by progress to be more conservative as the stream ends
    if is_new_bin {
        score += 25.0 + (progress * 50.0);
    }

    // Interaction term: penalize leaving space smaller than the next expected item
    // If next_item_size is 0, we assume a small default to avoid extreme bias
    let lookahead = if next_item_size == 0 { 20.0 } else { next_item_size as f64 };
    if post_residual > 0 && (post_residual as f64) < lookahead {
        score += (lookahead - post_residual as f64) * 1.5;
    }

    // Dynamic pressure: If many bins are open, favor filling existing ones (Best-Fit principle)
    // If only one bin fits, prioritize it strongly to avoid fragmentation
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // Smooth non-linear coupling: avoid creating "dead zones" (residuals between 1 and 9)
    // because they are statistically hard to fill with items (min 10)
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 5.0;
    }

    // Encourage balance: penalize bins that deviate significantly from the mean residual
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Harmonic classes logic: prioritize bins that leave residuals which are multiples of 
    // common item sizes or small divisors of the capacity.

    let mut score = post_residual as f64;

    // 1. Penalty for creating "orphan" space that is too small for any likely future item (under 10).
    if post_residual < 10 && post_residual > 0 {
        score += 45.0;
    }

    // 2. Harmonic alignment: Favor residuals that are divisors of the capacity (e.g., 20, 25, 50).
    // This maximizes the probability of filling the bin perfectly later.
    if bin_capacity % (post_residual + 1) == 0 {
        score -= 15.0;
    }

    // 3. Lookahead optimization: If the next item fits into the current post_residual, 
    // we prioritize this bin heavily to clear the item queue.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    }

    // 4. Density preservation: Penalize opening a new bin if we have many fitting options.
    // If we are forced to open a new bin, penalize it relative to the average bin efficiency.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0;
        } else {
            score += (mean_residual * 0.5);
        }
    }

    // 5. Progression scaling: As the stream nears the end, be more aggressive about 
    // closing bins (lower residual is better).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    // 6. Best Fit Decreasing logic: Favor bins that are already tightest.
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
