    // We penalize residuals that are smaller than the smallest likely item (e.g., < 10)
    // but only when we are not at the very end of the stream.
    if post_res < 10.0 && post_res > 0.0 {
        score += (10.0 - post_res) * (1.0 - progress).powf(0.5) * 5.0;
    }

    // Heuristic: If we are late in the stream, favor filling bins tightly to avoid new bin creation.
    // If we are early, we can afford slightly higher residuals to keep bins open for future variance.
    if fitting_bins_count > 0 {
