        0.0
    };

    // Reward bins that keep the post-residual close to the mean_residual to maintain uniformity.
    let uniformity_bonus = (post - mean_residual).abs() * 0.5;

    // Lookahead logic: if next_item_size exists, penalize bins that cannot fit it.
    // This effectively implements a "Best-Fit" with lookahead awareness.
    let lookahead_penalty = if next_item_size > 0 && post < next_item_size as f64 {
        (next_item_size as f64 - post) * (1.0 + progress)
    } else {
        0.0
    };

    // If this is a new bin, we penalize it based on how many existing bins could have fit the item.
    // Opening a new bin is only desirable if the existing fits are extremely poor.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (fitting_bins_count as f64 * 25.0) + (1.0 - progress) * 20.0
    } else {
        0.0
    };

    // Base score is the post_residual itself (Best-Fit principle).
    // We combine the terms to form a non-linear objective.
    let score = post + fragmentation_penalty + uniformity_bonus + lookahead_penalty + new_bin_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the least space (lower post_residual is better)
    // 2. Harmonic penalty: heavily penalize post_residuals that are too small to fit common items
    // If post_residual is in (0, 10), it is likely "dead space" for items 10-80.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 3. Lookahead integration: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize this placement.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
    }

    // 4. Harmonic thresholding: Favor bins that leave room for specific item-class complements.
    // If post_residual is near 25, 33, or 50, it aligns with common item divisors.
    let rem = post_residual % 25;
    if rem < 5 {
        score -= 10.0;
    }

    // 5. New bin management:
    // If this is a new bin (bin_residual == bin_capacity), only open if existing bins are poor fits.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other options exist, unless the mean residual is very high.
            score += 40.0 + (mean_residual * 0.5);
        } else {
            // No other choice.
            score = 0.0;
        }
    }

    // 6. Global pressure: As we approach the end of the stream, prioritize space density.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0) * (open_bins_count as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
