    }

    // 3. Fragmentation Control: Penalize leaving small gaps that are hard to fill.
    // A gap between 1 and 9 is usually "dead space".
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - progress);
    }

    // 4. Global State Awareness:
    // If we have many open bins, prioritize filling existing ones to keep open_bins_count low.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64) * 0.5;
    }

    // 5. New Bin Thresholding:
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // unless it's the only option or the progression suggests we are near the end.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other options exist.
            score += 85.0 + (progress * 20.0);
        } else {
            // We have no choice, make this the baseline.
            score = 50.0;
        }
    }

    // 6. Mean Residual Balancing:
    // If current bin is significantly emptier than the average, it's a good candidate for smaller items.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

