    // We penalize larger residuals quadratically.
    let mut score = post * post;

    // Lookahead logic: If we have a next item, penalize bins that will not fit it 
    // effectively. If post_residual is smaller than next_item_size, we increase the score
    // to discourage picking this bin if other options exist.
    if next_item_size > 0 {
