    // Progression logic: As the stream nears the end, we become more aggressive 
    // in packing tightly to avoid opening new bins.
    let density_factor = 1.0 - (mean_residual / bin_capacity as f64);
    score -= progress * density_factor * 50.0;

    // Handle the "new bin" case: 
    // If this is a new bin (residual == capacity), we set a high baseline cost 
    // to force the algorithm to prefer existing bins unless the 'post' penalty
    // for existing bins is extremely high.
    if bin_residual == bin_capacity {
        // The cost of opening a new bin is dynamic: higher early on, 
        // but becomes a "necessary evil" as fitting_bins_count decreases.
        score = 250.0 + (progress * 100.0) - (fitting_bins_count as f64 * 20.0);
    } else {
        // Adjust score based on how many other bins could take this item.
        // If fitting_bins_count is low, this bin is more precious.
        score -= (fitting_bins_count as f64).ln() * 5.0;
    }

