        }
    } else {
        // Reward filling bins that are already quite empty to reduce total bin count.
        if post_residual < 20 {
            score -= 10.0;
        }
    }

    // 5. Fragmentation Avoidance: Penalize leaving "dead space" (e.g., < 10 units)
    // that is too small for most items (assuming min size ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating small, unusable gaps (1..10) as they are likely to be wasted.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0;
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // reward this bin to keep the next item compact.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // Dynamic thresholding based on stream progress.
    // As we approach the end of the stream, prioritize aggressive packing (lower residuals).
    // If we have many open bins, penalize opening a new one (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 20.0 * (1.0 - progress);
    }

    // Interaction term: penalize bins that deviate significantly from the mean residual
    // to encourage uniform fill levels across the set of open bins.
    let dev = (post - mean_residual).abs();
    score += dev * 0.5;

    // Favor bins that are tight fits (lower post_residual) more heavily 
    // when fitting_bins_count is low (i.e., we are running out of options).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base Strategy: Best Fit (minimizing post_residual)
    // 2. Penalty for opening new bins: if bin_residual == bin_capacity, this is a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is already very tight (< 15)
        // or if we are forced to (fitting_bins_count == 0).
        if fitting_bins_count > 0 && mean_residual > 15.0 {
            score += 1000.0;
        } else {
            score += 45.0; // Moderate cost to open a new bin
        }
    }

    // 3. Harmonic Logic: Favor residuals that are multiples of common item sizes (e.g., 20, 25, 33)
    // to leave space for future items.
    let harmonic_penalty = (post_residual % 20) as f64 * 0.5;
    score += harmonic_penalty;

    // 4. Lookahead coupling: If next_item_size is large, avoid creating a post_residual
    // that is slightly smaller than the next item (creating "dead space").
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 5 {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
        // Reward if post_residual is a perfect fit for the next item
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 5. Progression awareness: As we approach the end of the stream, tighten requirements
    // to avoid leaving too many bins half-empty.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    // 6. Penalty for creating "unusable" tiny fragments (1-9)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is small (1-9), it is highly likely to be wasted.
    // We penalize these "sliver" gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 2. Lookahead Synergy: If the next item can fit perfectly or near-perfectly into the 
    // current post_residual, prioritize this bin.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs();
        if diff == 0 {
            score -= 40.0;
        } else if diff < 5 {
            score -= 20.0;
        }
    }

    // 3. Open Bins Pressure: Penalize opening new bins when many are already active.
    // If this is a new bin (bin_residual == bin_capacity), increase score based on current open_bins_count.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
    }

    // 4. Last Chance Heuristic: If this is the only bin that can fit the item, 
    // significantly reduce the score to ensure we don't force a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Global Density Awareness: As the stream progresses, favor tighter packing 
    // (lower post_residual) to reduce fragmentation in the final stages.
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    score += progress * (post_residual as f64 * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Heavily punish creating very small, unusable gaps (dead space).
    // Gaps between 1 and 9 are almost always useless given the item range.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead matching: If the next item fits perfectly into the post_residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item perfectly
            let diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - diff) * 0.5;
        } else {
            // Penalize if this bin will definitely be too small for the next item
            score += 15.0;
        }
    }

    // 3. Conservation: If this is the only bin that can fit the current item, 
    // prioritize using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // 4. Global Load Balancing: Avoid fragmenting bins if we are far from the end.
    // If the current bin is emptier than the mean, prefer keeping it open.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // 5. New Bin Thresholding: 
    // If bin_residual == bin_capacity, we are evaluating the cost of opening a new bin.
    // We increase the cost of opening a new bin as the stream progresses to force consolidation.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 + (progress * 30.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: minimize post_residual (already in score)
    // 2. Penalize "dead space" (gaps < 10 are rarely useful for items >= 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead optimization: If next item fits, prefer bin where it still fits
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            // Penalize if we block the next item from fitting in this bin
            score += 15.0;
        }
    }

    // 4. Global State pressure: If we are deep in the stream, favor tighter packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 5. If this is a new bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if fitting is poor
        if open_bins_count > 0 {
            score += 40.0 + (mean_residual * 0.5);
        }
        // If it's the only choice, keep it neutral
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    } else {
        // 6. Prefer bins that are already "half-full" to keep others empty
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fullness * 20.0;
    }

    // 7. Last chance heuristic: If only one bin can fit this, prioritize it strongly
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: punish larger post_residuals (Best Fit logic)
    let mut score = post;

    // Penalize the creation of a new bin (bin_residual == bin_capacity)
    // We scale this penalty by the progress; as the stream nears the end, 
    // we become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 + progress);
    }

    // Lookahead coupling: If the next item is large, prioritize keeping 
    // the current bin's post_residual large enough to accommodate it.
    if next_item_size > 0 {
        let diff = (next_item_size as f64) - post;
        if diff > 0.0 {
            // Penalize slots that cannot fit the next item
            score += diff * 1.5;
        } else {
            // Reward slots that can fit the next item
            score -= (100.0 - diff.abs()) * 0.2;
        }
    }

    // Stability coupling: Discourage fragmentation by penalizing bins 
    // that deviate significantly from the mean residual of open bins.
    let residual_variance = (post - mean_residual).abs();
    score += residual_variance * 0.5;

    // Scarcity coupling: If this is the only bin that can fit the item,
    // lower its score significantly to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Non-linear penalty for creating very small, unusable slivers of space (dead space)
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but not zero (fragmentation).
    // If post_residual is in [1, 9], it's likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 - (post_residual as f64 * 4.0);
    }

    // 2. Lookahead Coupling: If next_item_size exists, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // Strong preference for bins that can fit the next item.
        } else {
            // If we can't fit next item, penalize proportionally to how much space is left.
            score += (post_residual as f64) * 0.2;
        }
    }

    // 3. Density Balancing: If we have many open bins, penalize opening a new one.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += (open_bins_count as f64) * 15.0;
        // Discourage new bin if an existing bin could fit the current item well.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 4. Harmonic Modulo Bias: Favor residuals that are multiples of common item sizes (e.g., 20, 25).
    // This helps keep bins "aligned" for future items.
    let remainder = post_residual % 20;
    if remainder == 0 {
        score -= 10.0;
    } else if remainder > 15 {
        score += 5.0;
    }

    // 5. Progression Scaling: As the stream nears the end, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize leaving small, unusable fragments (1..9).
    // These gaps are too small for any item (min size 10), so they are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Best-Fit Coupling: Reward bins that become tight.
    // If post_residual is 0, it's a perfect fit.
    if post_residual == 0 {
        score -= 20.0;
    }

    // 3. Lookahead Integration: If the next item can fit in this post_residual, prioritize it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    // 4. Global Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a penalty based on open_bins_count.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 0.5);
    }

    // 5. Mean Residual Balancing: Avoid bins that deviate significantly from the average.
    // This helps keep the "density" of bins consistent.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 6. Scarcity Constraint: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize smaller post_residual (Best Fit).
    // We reward bins that leave very little space (0-5 range) as "perfect" fits.
    if post_residual < 5 {
        score -= 50.0;
    }

    // 2. Lookahead matching: If next_item_size fits in the post_residual, 
    // highly reward this bin to create a "perfect pair".
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 120.0;
        // Further refine: if the remaining space after next_item is small, it's even better.
        let residue_after_next = post_residual - next_item_size;
        if residue_after_next < 10 {
            score -= 40.0;
        }
    }

    // 3. Penalty for "Dead Zones": post_residual values between 1 and 9 are often
    // unusable given the item size distribution (min 10).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // 4. Global state awareness: If we have many open bins, penalize opening a new one 
    // (bin_residual == bin_capacity). 
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 90.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 5. Mean-Residual alignment: If this placement makes the bin's residual 
    // significantly worse than the current mean_residual, penalize it.
    if (post_residual as f64) > mean_residual * 1.5 {
        score += 20.0;
    }

    // 6. Urgency: If fitting_bins_count is low, we are running out of options.
    // Reduce penalty for using a bin if it's one of the few that fit.
    if fitting_bins_count <= 2 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual: The space left if we pick this bin.
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize configurations that leave very small, unusable gaps (e.g., 1-9).
    // This encourages filling bins tightly.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead Coupling: If the next item fits into the current bin's post_residual,
    // lower the score to prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. New Bin Threshold: If this is an empty bin (bin_residual == bin_capacity),
    // penalize opening it based on the number of already open bins.
    if bin_residual == bin_capacity {
        // Only open a new bin if we are struggling to fit items into existing ones.
        score += (open_bins_count as f64) * 2.0;

        // If we have many fitting bins, don't open a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Global State Balancing: If the mean residual of current bins is high,
    // we want to use those bins (lower score) to consolidate space.
    if mean_residual > 30.0 && bin_residual < bin_capacity {
        score -= (mean_residual / 2.0);
    }

    // 5. Dynamic Horizon: As we approach the end of the stream, prioritize 
    // closing existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
