}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // We scale the penalty based on how many bins are already open and the progress of the stream.
    // As we approach the end of the stream, we become more conservative about opening new bins.
    if is_new_bin {
        score += 25.0 + (open_bins_count as f64 * 2.0) - (progress * 15.0);
    }

    // Lookahead logic:
    // If we have a next item, penalize leaving a post_residual that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // High penalty for creating a "gap" that is too small for the immediate future
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward creating a residual that fits the next item perfectly
            score -= (100.0 - (post_residual as f64 - next_item_size as f64).abs()) * 0.1;
        }
    }

    // Dynamic pressure:
    // If few bins can fit the current item, prioritize the ones that have higher residual to save space
    // for smaller items, but penalize creating "dead zones" (residuals < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (1.0 - progress);
    }

    // Interaction between mean_residual and current fit:
    // If the bin is significantly emptier than the global mean, it's a "cold" bin.
    // Prefer using "warm" bins (those closer to the mean) to consolidate space.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
