    let harmonic_penalty = (post_residual % 25) as f64 * 0.5;
    score += harmonic_penalty;

    // 5. New bin management: If this is a new bin (residual == capacity), 
    //    only open if fitting_bins_count is very low or if existing bins are 
    //    "clogged" (mean_residual is very low).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
