        } else {
            // Heavily penalize opening a new bin if we have fitting options
            score += 45.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 6. Dynamic Scaling: As we approach the end of the stream, 
    //    tighten the constraints on bin usage.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

