    // 4. Pressure management: If fitting_bins_count is low, we are running out of options.
    // Discourage creating new bins when we have many open bins that are nearly empty.
    if fitting_bins_count == 0 && open_bins_count > 5 {
        score += 20.0;
    }

    // 5. Reward keeping residuals close to the global mean to maintain bin uniformity
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

