        }
    }

    // 3. New Bin Thresholding: 
    // If the current bin is empty (new bin candidate), penalize it unless the item is large 
    // or we are near the end of the stream where efficiency is less critical than clearing.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other options exist, unless the item is very large
            score += 40.0 + (item_size as f64 * 0.5);
        } else {
            // Must open a new bin
            score = 0.0;
        }
    }

    // 4. Global Density Awareness:
    // If we have many bins open, penalize creating more dead space relative to the mean.
    if open_bins_count > 0 {
        if post_residual as f64 > mean_residual {
            score += (post_residual as f64 - mean_residual) * 0.8;
        }
    }

    // 5. Progression Weighting:
    // As we approach the end of the stream, prioritize fitting items into existing bins 
    // to avoid leaving partially filled bins hanging.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

