        }

        // 5. Global state balancing: if this bin's residual is significantly better than the mean, prioritize it
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }

        // 6. Tightness heuristic: Favor bins that leave very little space (Best Fit)
        // We subtract a portion of the post_residual to make it the primary sorting key
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

