}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining capacity. Lower is better (Best Fit).
    let mut score = post;

    // Penalty for opening a new bin:
    // If bin is empty (new bin candidate), apply a dynamic penalty based on progress and current efficiency.
    // As the stream nears the end, we become less picky about creating new bins to avoid fragmentation.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 15.0 + (mean_residual * 0.5) * (1.0 - progress);
        score += new_bin_penalty;
    }

    // Lookahead interaction:
    // If next_item_size exists, penalize bins that cannot fit it after current placement.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize creating a bin that is too small for the next item.
            // Scale this penalty by how close we are to the end of the stream.
            score += (next_item_size as f64 - post) * (1.0 + progress);
        } else {
            // Reward bins that are perfectly sized to fit the next item.
            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // High-density optimization:
    // If only one bin can fit the current item, prioritize it heavily to avoid unnecessary bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Non-linear coupling: 
    // Penalize bins that leave very small 'dead' space (e.g., 1-5 units) 
    // which are statistically unlikely to be filled.
    if post_residual > 0 && post_residual < 6 {
        score += (6.0 - post) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize post_residual while penalizing "fragmentation" (small, unusable remainders).
    // Use harmonic classes: bins that leave space for common item sizes are prioritized.

    let mut score = post_residual as f64;

    // 1. Penalize small, unusable remainders (dead space)
    // If post_residual is < 10, it's likely unusable as most items are >= 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
