    // unless no other bins can fit the item or the mean residual is already very high.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 100.0;
        } else {
            score += 10.0;
        }
    }

    // 4. Harmonic balancing
    // Favor bins that align with the mean usage of current bins to keep them uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 5. Progression scaling
    // As we reach the end of the stream, prioritize tight fitting to clear leftovers.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
