    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 2.0);
        // If there are other bins that could fit this, discourage opening a new one
        if fitting_bins_count > 1 {
            score += 100.0;
        }
    }

    // 4. Global efficiency adjustment:
    // Balance the residual against the mean to prevent bin fragmentation.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (residuals too small for common items, but too large for efficiency)
    // If post_residual is between 1 and 9, it is extremely unlikely to fit another item.
    if post_residual > 0 && post_residual < 10 {
