    // 2. Lookahead optimization: If the next item fits perfectly in the new residual, reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // Reward bins that keep enough space for the next item without being too empty
            score -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
        }
