            score += 40.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // 4. Prefer bins that keep the mean_residual stable or lower.
        // We want to avoid fragmenting space; prioritize bins closer to the current mean.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // 5. If this is the last fitting bin, slightly penalize it to discourage "bad" fits if a better one exists,
    // but keep it viable to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score. 
