    // 3. Global state: If we are late in the stream, favor closing bins (lower mean_residual)
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += mean_residual * 0.5;
    }

    // 4. Handle the "New Bin" decision:
    // If bin_residual == bin_capacity, this is a new bin. 
    // Only pick this if fitting_bins_count is low or current fits are terrible.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
