        } else {
            // Heavily penalize opening a new bin if other options exist
            score = 100.0 + (open_bins_count as f64 * 2.0);
        }
    } else {
        // Reward filling existing bins to minimize open_bins_count
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
