    // 2. Lookahead Synergy: If the next item can fit in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Penalize opening a new bin if we have existing capacity.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            // Apply a heavy penalty to open a new bin if there are other bins available.
            score += 40.0 + (open_bins_count as f64 * 2.5);
        }
    } else {
        // 4. Fitting Scarcity: If this is the last bin that can fit the item, 
        // prioritize it to avoid forcing a new bin later.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // 5. Global Efficiency: If the current post_residual is significantly better than 
    // the mean residual of open bins, reward the placement to keep bins tight.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large post-residuals to keep bins tight.
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If the post-residual can accommodate the next item, heavily reward it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward perfect or near-perfect fits for the next item
            let fit_diff = (post_residual - next_item_size) as f64;
            score -= (100.0 - fit_diff) * 2.0;
