    // 2. Harmonic Class Logic: Reward placements that leave a residual 
    // that is a multiple of common item sizes (e.g., 20, 25, 33, 50).
    // This helps packing future items by creating "clean" remaining space.
    let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_penalty * 0.4;

    // 3. Lookahead Synergy: If post_residual is close to next_item_size, 
