    // Lookahead logic: if the next item is large, favor bins that can accommodate it.
    // If the current post_residual is smaller than the next item, we penalize the bin.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
    }

    // Dynamic thresholding: as the stream progresses, become more aggressive 
    // about filling existing bins to reduce the total open_bins_count.
    score += (open_bins_count as f64) * (1.0 + progress);

    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty 
    // that decays as the stream progresses and the mean residual of existing bins increases.
    // This forces the algorithm to use existing bins unless they are extremely poor fits.
    if bin_residual == bin_capacity {
        score += (bin_capacity as f64 - mean_residual) * (2.0 - progress);

        // If there are other bins that can fit the item, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 150.0 * (1.0 - progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #531: Harmonic Residual Optimization
    // Targets the minimization of "orphan" space by penalizing post_residuals 
    // that are unlikely to accommodate the next item or future high-probability sizes.

    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Penalize residuals that are small but not zero,
    // as they create "dead space" that cannot fit common item size ranges (e.g., < 10).
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    // 2. Lookahead Coupling: If the next item fits into the current post_residual, 
    // reward this placement heavily to encourage "perfect packing" sequences.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // 3. Fragmentation Control: If this is the only bin that fits the item, 
