    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 4. New Bin Threshold: Discourage opening a new bin unless the current 
    // mean residual suggests we are wasting space across the board.
    if bin_residual == bin_capacity {
        score += 35.0; 
        if mean_residual < 20.0 {
            score += 20.0;
        }
    }

    // 5. Progress Normalization: As the stream nears completion, become more 
    // aggressive in fitting items into existing bins to minimize final bin count.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

