}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #532: Strict Best-Fit with Adaptive Dead-Space Penalty and Open-Bin Pressure.
    // Logic: 
    // 1. Primary: Best-Fit (minimize post_residual).
    // 2. Penalty: If post_residual is in the "danger zone" (1..9), penalize heavily to avoid creating unfillable slivers.
    // 3. Pressure: Increase cost of opening new bins as the stream progresses.
    // 4. Lookahead: Prefer placements that leave enough space for the next item if possible.

    let mut score = post_residual as f64;

    // Penalty for "Dead Space": Gaps smaller than the minimum possible item (10) are usually wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // New Bin Penalty: If this is an empty bin, calculate cost based on current bin load pressure.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have no other options, or if open_bins_count is very low.
        score = 25.0 + (open_bins_count as f64 * 2.0);

        // As we approach the end of the stream, discourage opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 40.0;
    } else {
        // If this is an existing bin, reward placements that keep the bin "balanced" 
        // relative to the mean residual of all open bins.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score -= deviation * 0.1;
    }

    // Lookahead logic: If the next item exists, penalize bins that cannot fit it 
    // after the current item is placed, if that bin was the only option.
    if next_item_size > 0 && post_residual < next_item_size {
        if fitting_bins_count == 1 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
