    // 2. Lookahead optimization: if next_item_size is known, favor bins that leave enough space for it.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 3. Open bins pressure: If we are using many bins, penalize opening new ones (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
        // Further penalize opening a new bin if we are near the end of the stream to consolidate.
        score += (step_index as f64 / total_items as f64) * 15.0;
    }

    // 4. Fitting constraints: If this is the only bin that fits the item (fitting_bins_count == 1), 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Balance residuals: If this bin's residual is significantly below the mean, it's a "tight" bin.
    // Tight bins are good for packing efficiency if they don't become dead space.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score (Best Fit Decreasing variant with lookahead)
    // post_residual: smaller is better (Best Fit).
    // post_residual == 0: Perfect fit, heavily prioritized.
    // next_item_size: If post_residual is close to next_item_size, we reward it to create a "perfect combo".

    let mut score = post_residual as f64;

    // 1. Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2. Lookahead: Reward bins that can accommodate the next item perfectly
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        // If we can fit the next item exactly, give a massive boost
        if diff == 0.0 {
            score -= 45.0;
        } else {
            // Otherwise, reward bins that leave just enough space for the next item
            score -= (20.0 / (diff + 1.0));
        }
    }

    // 3. Penalty for fragmentation
    // If post_residual is small but > 0, it's often "dead space" (e.g., 1-9).
    // Penalize these unless it's a very tight fit.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 4. Global state awareness:
    // If this is a new bin, penalize it relative to how many bins are already open
    // unless the open bins are all very full (mean_residual is low).
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 0.5) - (mean_residual * 0.2);
    }

    // 5. Fitting constraint:
    // If this is the ONLY bin that fits the current item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
