    // 4. Density Optimization: Encourage filling bins closer to the mean_residual
    // This helps keep the distribution of remaining space uniform
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 5. Urgency: If this is the only bin that fits the item, make it highly attractive
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Scale for large sequences: Tighten constraints as we reach the end of the stream
    if progress > 0.95 {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
