        // Increase penalty for opening new bins as we reach the end of the stream
        score += (step_index as f64 / total_items as f64) * 50.0;
    }

    // 4. Harmonic Alignment: Favor residuals that are multiples of common item 
    // sizes (e.g., 20, 25, 50) to leave room for future items.
    let alignment = post_residual % 25;
    score += alignment as f64 * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

