pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating bins with tiny residuals (fragmentation) 
    // unless it is the very end of the stream.
    let fragmentation_penalty = if post_res < 10.0 && post_res > 0.0 {
        (10.0 - post_res) * (1.0 + progress * 5.0)
    } else {
        0.0
    };

    // Evaluate the benefit of keeping a "tight" fit vs "loose" fit
    // based on lookahead. If the next item is large, we want higher post_residual.
    let lookahead_penalty = if next_item_size > 0 {
        if post_res < next_item_size as f64 {
            (next_item_size as f64 - post_res) * 0.8
        } else {
            0.0
        }
    } else {
        0.0
    };

    // If this is a new bin, penalize based on current bin count to favor packing
    // into existing bins, but reduce this penalty as the stream progresses.
    let new_bin_penalty = if bin_residual == bin_capacity {
        (open_bins_count as f64 * 2.0) * (1.0 - progress * 0.5)
    } else {
        0.0
    };

    // Favor bins that align with the global mean residual to keep distribution uniform
    let uniformity_bonus = (post_res - mean_residual).abs() * 0.2;

    let score = post_res + fragmentation_penalty + lookahead_penalty + new_bin_penalty + uniformity_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post_residuals (dead space)
