    score += post_residual as f64 * 0.5;

    // 2. Lookahead Logic: If next_item_size fits in the post_residual, reward this placement
    // This implements a primitive Best-Fit-Decreasing-like lookahead.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.2;
    }

    // 3. Harmonic Class Logic:
    // Penalize residuals that are small but not zero (fragmentation).
    // If post_residual is in (0, 10), it's likely "wasted" space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. New Bin Threshold:
    // If this is a new bin (bin_residual == bin_capacity), penalize it unless 
    // it's the only option or the current open bins are very full.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // High penalty for opening a new bin if an existing bin fits
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Neutral score for empty bin if no other option exists
            score -= 10.0;
        }
    }

    // 5. Global Efficiency Adjustment:
    // As the stream progresses, become more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 6. Mean Residual Balancing:
    // Avoid bins that deviate significantly from the mean_residual to keep packing uniform.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Penalize post_residual values that create unusable "slivers" (1-9).
    // These gaps are too small for most items (10..80 range), wasting potential capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
