    // 2. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // scaled by the current number of open bins to consolidate items.
    if bin_residual == bin_capacity {
