    // This helps avoid creating a mix of very full and very empty bins.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.3;

    // 5. Urgency: If this is the only bin that can fit the item, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
