pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual represents the "wastage" if we place the item here.
    // We want to minimize post_residual while considering lookahead and global state.

    let mut score = post_residual as f64;

    // 1. Penalize creating very small "dead space" that is unlikely to fit future items.
    // If post_residual is small but > 0, it is often worse than 0 (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 2. Incorporate lookahead: If next_item_size is known, penalize bin choices that 
    // leave too little room for it, unless it's a perfect fit.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 20.0;
        }
    }

    // 3. Global state: If we have many bins open, we want to consolidate.
    // Penalize opening a new bin (where bin_residual == bin_capacity) if we have 
    // other bins that can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if an existing one works.
            score += 50.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If it's our only choice, keep the score low.
            score -= 5.0;
        }
    }

    // 4. Dynamic time horizon: As we approach the end of the stream, 
    // prioritize closing existing bins (lower residual) over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (mean_residual - post_residual as f64) * 0.5;
    }

    // 5. Tie-breaker: If post_residual is 0, strongly reward it.
    if post_residual == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalty for opening a new bin when existing options exist
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin && fitting_bins_count > 0 {
        // As the stream progresses, we become more aggressive in opening new bins
        // to avoid "trapping" large items in late-stage bins.
        (1.0 - progress) * 50.0 + (fitting_bins_count as f64 * 2.0)
    } else {
        0.0
    };

    // Best-Fit Decreasing logic: reward smaller post_residual (tighter fit)
    // Non-linear coupling: square the residual to penalize large gaps exponentially
    let mut score = post * post / bin_capacity as f64;

    // Lookahead interaction: if the next item is large, favor bins that can accommodate it.
    // If the current post_residual is too small to fit the next item, penalize it slightly.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
