    // Lookahead logic: If the next item fits into the current post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (1.0 - (post_res - next_item_size as f64) / bin_capacity as f64);
    }

    // Dynamic thresholding: As the stream progresses, prioritize closing bins (lower residual)
    // to avoid fragmentation, but allow new bins if the current fit is poor relative to the mean.
    if bin_residual != bin_capacity {
        // Penalty for bins that deviate significantly from the mean residual
        let deviation = (post_res - mean_residual).abs();
        score += 5.0 * (deviation / bin_capacity as f64) * progress;
    } else {
        // New bin penalty: increases linearly with progress to force consolidation.
        // We only open a new bin if the existing fits are objectively terrible.
        score += 40.0 * (1.0 + progress) + (open_bins_count as f64 * 0.5);
    }

    // If this is the only bin that fits the item, make it highly desirable to avoid opening new ones.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

