        score += (open_bins_count as f64) * 2.5;
        // Further penalize if we have bins that could have fit the item.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 4. Global Density Awareness: If current bin is emptier than average, 
    // prefer filling it to consolidate space.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    // 5. Final refinement: Favor bins where the item fits "snugly" (Best Fit logic).
    // This naturally minimizes post_residual while avoiding the penalty zone.
    score += (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

