        }
    } else {
        // Encourage filling bins that are already below average fullness (high residual).
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        }
    }

    // 4. Progression adjustment:
    // As we approach the end of the stream, be more conservative with opening new bins.
    let progress = step_index as f64 / total_items as f64;
