pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the residual space after placement
    let mut score = post_res;

    // Penalty for creating a bin that is "too empty" if we are near the end of the stream
    // We prioritize tighter packing as the stream progresses to minimize total bins.
    if bin_residual == bin_capacity {
        // This is a new bin. Penalize opening it based on how many bins are already open 
        // and how much space is left on average.
        score += (open_bins_count as f64 * 2.0) + (mean_residual * progress);
    } else {
        // For existing bins, reward placements that result in smaller residuals (Best Fit).
        // We use a non-linear decay to avoid creating small "dead" fragments.
        score += (post_res * post_res) / (bin_capacity as f64);

        // If this is the last fitting bin, we apply a strong incentive to use it
        // to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 20.0;
