    }

    // Lookahead influence: if the next item is large, prioritize bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we penalize the bin slightly 
    // because it will force a new bin for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_res) * 0.5;
    }

    // Interaction term: Couple progress with the mean residual to penalize 
    // fragmented states in the late stages of the stream.
    score += (mean_residual * progress * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
