        score += mean_residual * 2.5;

        // If we have many open bins, penalize opening another one heavily.
        score += (open_bins_count as f64) * 5.0;
    } else {
        // 2. Harmonic Class Logic: Reward placements that leave "useful" residuals.
        // Residuals that are multiples of common item sizes (e.g., 20, 25, 50) are more versatile.
        let residue_mod = (post_residual % 25) as f64;
