    if progress > 0.8 {
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    // 5. Urgency: If this is the last chance for this item, reduce penalty for poor fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
