    // apply a strong reward (negative score).
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - diff) * 1.5;
    }

    // 3. Global Efficiency: If this is the only bin that fits the item, 
    // prioritize it to avoid opening unnecessary new bins.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // 4. New Bin Penalty: Heavily penalize opening a new bin unless the 
    // current residuals are extremely poor (i.e., this bin is truly empty).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 65.0;
        }
    }

    // 5. Residual Balancing: If the post_residual is below the current mean, 
    // it is a "tight" fit, which is generally good to keep open bins packed.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 6. Progression Scaling: As the stream nears completion, become more 
    // aggressive about filling existing bins to reduce the final bin count.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Best-Fit Penalty: Minimize post_residual (Best-Fit principle)
    // Already in score: higher post_residual increases score (worse).

    // 2. Lookahead Coupling: If next_item can fit in post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 45.0 * (1.0 - progress);
    }

    // 3. Fragmentation Avoidance: If post_residual is small but > 0, it's "dead space".
    // Penalize small remainders that are unlikely to fit future items.
    if post_residual > 0 && post_residual < 15 {
        score += 30.0;
    }

    // 4. Global State: If we have many open bins, prioritize packing into existing ones.
    if !is_new_bin {
        score -= (open_bins_count as f64).sqrt() * 5.0;
    } else {
        // High penalty for opening a new bin if we have many fitting options.
        score += (fitting_bins_count as f64) * 20.0;
        // Encourage new bins only when necessary or late in the stream.
        score += (1.0 - progress) * 25.0;
    }

    // 5. Mean Residual Alignment:
    // If this bin's post_residual is significantly better than the global mean, reward it.
    if (post_residual as f64) < mean_residual {
        score -= 10.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating bins that are nearly empty (fragmentation)
    // Reward bins that minimize post_residual (Best Fit)
    // Non-linear coupling: as progress increases, become more aggressive at filling gaps
    let fragmentation_penalty = (post_res * post_res) / (bin_capacity as f64);

    // Lookahead logic: if next_item_size fits in current post_residual, reward this bin
    let mut lookahead_bonus = 0.0;
    if next_item_size > 0 && next_item_size <= post_residual {
        lookahead_bonus = -20.0 * (1.0 - progress);
    }

    // Scarcity adjustment: if this is the only bin that fits, prioritize it heavily
    let scarcity_bias = if fitting_bins_count == 1 { -50.0 } else { 0.0 };

    // Handle the NEW-BIN CANDIDATE case (bin_residual == bin_capacity)
    // We penalize opening new bins unless the residual in existing bins is very poor
    let new_bin_penalty = if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of current bins is already quite low
        // or if we are early in the stream (to keep options open)
        (100.0 * (1.0 - progress)) + (mean_residual * 0.5)
    } else {
        0.0
    };

    // Combine factors
    // We want to minimize the score, so bonuses are negative
    fragmentation_penalty + lookahead_bonus + scarcity_bias + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Minimize post_residual
    // (Already inherent in the base score, but we refine it based on bin state)

    // 2. Penalty for creating "dead space" (residuals < 10 are often unusable)
    // If the post_residual is small but > 0, it's a "bad" fit unless it's 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead heuristic: If the next item can fit in the current post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
