        score += deviation * 0.1;
    }

    // 5. Thresholding for new bin:
    // If we only have one fitting bin, avoid opening a new bin unless the fit is truly terrible
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Apply a heavy penalty to opening a new bin if an existing one can fit the item
            score += 60.0;
        }
        // Penalize opening new bins late in the stream
        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // 6. Modulo-based "Bin Packing Efficiency" bias:
    // Encourage filling bins to high capacity (e.g., multiples of 20)
    let fill = bin_capacity - post_residual;
    let remainder = fill % 20;
    if remainder > 15 {
        score -= 5.0; // Reward nearing the next 20-unit threshold
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
