    if post_residual > 0 && post_residual < 10 {
        score += 500.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item can fit perfectly into the current post_residual,
    // reward this placement significantly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_diff = (post_residual - next_item_size) as f64;
        score -= 150.0 / (fit_diff + 1.0);
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless the fit is excellent.
    // If bin_residual == bin_capacity, this is a new bin candidate.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many bins already open
        score += (open_bins_count as f64) * 20.0;

        // Only open a new bin if the item is large (minimizing wasted space)
        if item_size < 50 {
            score += 100.0;
        }
    } else {
        // 4. Tightness Reward: Favor bins where the post_residual is small (Best Fit).
        // If it's the last chance (fitting_bins_count == 1), lower the penalty to accept the fit.
        if fitting_bins_count > 1 {
            score += (post_residual as f64) * 0.5;
        }
    }

    // 5. Mean residual balancing: Penalize placements that deviate significantly from the mean
    // to keep bin utilization uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalty for opening a new bin prematurely
    if bin_residual == bin_capacity {
        score += 45.0; 
        if open_bins_count > 0 {
            score += (open_bins_count as f64) * 0.5;
        }
    }

    // 2. Lookahead optimization: prioritize bins where post_residual fits next_item_size
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that create a "perfect" landing for the next item
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
        } else {
            // Penalize creating "dead space" that cannot fit the next item
            score += 15.0;
        }
    }

    // 3. Balance against mean_residual to prevent fragmentation
    // If post_residual is significantly smaller than the global mean, it's a tight fit (good)
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 4. Force consolidation: penalize leaving bins with very small residuals 
    // that are unlikely to fit future items, unless it's a tight fit (near 0)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 5. If this is the only bin that fits, prioritize it heavily to avoid new bin creation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 6. Progressive scaling: as the stream nears the end, prioritize tight packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
