    // Small gaps (1-4) are "poison" for future items.
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }

    // 2. Lookahead Synergy: If next_item can fit in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // 3. Global State: If we are near the end of the stream, prioritize aggressive bin packing.
    // Otherwise, keep bins slightly more open to accommodate potential larger items.
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    } else {
        score += (mean_residual - post_residual as f64) * 0.5;
    }

    // 4. New Bin Logic: Discourage opening new bins unless the fit is extremely poor.
    // If bin_residual == bin_capacity, we are evaluating the cost of a new bin.
    if bin_residual == bin_capacity {
        // Only open new if we have many bins or the current fitting options are all "bad" (high residuals)
        if open_bins_count > 0 {
            score += 40.0 + (mean_residual * 0.5);
        }
    }

    // 5. Scarcity Constraint: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    let p_res = post_residual as f64;

    // Penalize new bin creation (bin_residual == bin_capacity) as the stream progresses
    // to force tighter packing later in the stream.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let new_bin_penalty = is_new_bin * (50.0 + (progress * 150.0));

    // Best-Fit Decreasing logic: Favor bins that result in small residuals (tight fit).
    // Square the residual to exponentially penalize large gaps.
    let fit_score = p_res * p_res * 0.01;

    // Lookahead: If the next item is large, avoid leaving a residual that is 
    // too small to accommodate the next item (Dead Space Minimization).
    let mut lookahead_penalty = 0.0;
    if next_item_size > 0 && p_res < next_item_size as f64 {
        // If this bin becomes unusable for the next item, penalize it.
        // We weigh this penalty higher when we have few fitting bins left.
        lookahead_penalty = (100.0 - p_res) * (1.0 / (fitting_bins_count as f64 + 0.1));
    }

    // Interaction term: If the bin is already quite empty (high mean_residual), 
    // avoid adding more items to it to keep the bin distribution uniform.
    let distribution_penalty = (mean_residual - p_res).max(0.0) * 0.5;

    fit_score + new_bin_penalty + lookahead_penalty + distribution_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Base penalty for creating "dead zones" (small residuals that cannot fit common items)
    // Residuals < 10 are highly undesirable as they are unusable for the defined input range.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Class Logic: Favor residuals that perfectly accommodate common item sizes
    // If the post_residual is a multiple of the next item size, it's a high-probability fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 15.0;
        }
    }

    // 3. Lookahead/Density Balancing
    // If we have many open bins, penalize opening new ones or choosing bins that leave too much space.
    if bin_residual == bin_capacity {
