        score += 25.0 + (open_bins_count as f64 * 0.5);
    } else {
        // If this bin is the last one that can fit the item, reward its selection to keep the bin count low.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // 4. Distributional progression: As the stream progresses, tighten tolerance for empty space.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0) * (post_residual as f64 / bin_capacity as f64);

    // 5. Mean-residual normalization: Penalize bins that deviate negatively from the average state.
    if (post_residual as f64) < mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
