    // unless the current fit is extremely poor.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (40.0 * (1.0 + progress)) + (open_bins_count as f64 * 0.5)
    } else {
        0.0
    };

    // Coupling: Favor tight fits (post_residual near 0) but balance with mean_residual
    // to prevent clustering items in already sparse bins.
    let efficiency_score = post_res + (post_res * (mean_residual / bin_capacity as f64));

    let mut score = efficiency_score + fragmentation_penalty + lookahead_penalty + new_bin_penalty;

    // Critical constraint: If this is the last chance for the item, lower the penalty 
    // to prevent aggressive forced new-bin creation.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    score
