        // 2. Lookahead matching: Reward bins that fit the next_item_size perfectly.
        // If post_residual is close to next_item_size, it's a high-value placement.
        if next_item_size > 0 && post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            score -= (20.0 / (1.0 + diff));
        }

        // 3. Avoid "Fragmenting": Penalize small residuals that are unusable (< 10).
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }

        // 4. Balance: Reward bins that stay near the global mean residual to keep bins uniform.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.1;
    }

    // 5. Urgency: If this is the last chance for the current item, reduce penalty for opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // 6. Progressive tightening: As the stream nears the end, be more aggressive with packing.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
