    }

    // If this is the only bin that fits, prioritize it heavily by reducing the score.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Normalize by the mean residual to keep the heuristic scale consistent.
    // This helps avoid opening new bins when current bins are already well-utilized.
    score += (mean_residual - post) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
