    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 25.0;
    }

    // 3. OPEN BINS PRESSURE
    // As the stream progresses, we become more conservative about opening new bins.
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // relative to how many bins are already open.
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64 * 2.0);
    }

    // 4. FRAGMENTATION BALANCING
    // If we have many open bins, prioritize filling the ones that are already 
    // "emptier" (higher mean_residual) to consolidate space.
    if open_bins_count > 0 {
        score -= (bin_residual as f64 - mean_residual) * 0.5;
    }

    // 5. URGENCY
    // If this is the last fitting bin, slightly reward placing here to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // ARCHETYPE: Aggressive 2-step lookahead matching
    // Objective: Minimize post_residual, but prioritize bins where the post_residual 
    // can accommodate the next_item_size effectively (Best-Fit-Lookahead).

    let mut score = post_residual as f64;

    // 1. Penalize opening a new bin unless existing bins are extremely poor fits
    if bin_residual == bin_capacity {
        // High penalty for new bins; only choose if open bins are too full to accommodate future items
        score += 45.0 + (mean_residual * 0.5);
    } else {
        // 2. Lookahead logic: Reward bins that leave exactly enough or slightly more 
        // space for the next item, effectively performing a Best-Fit-Decreasing style match.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Reward perfect or near-perfect fit for the next item
                let fit_diff = (post_residual - next_item_size) as f64;
                score -= (50.0 / (1.0 + fit_diff));
            } else {
                // Penalize placements that make the next item impossible to fit in this bin
                score += 15.0;
            }
        }

        // 3. Fragmentation control: Heavily penalize leaving a tiny sliver of space (1-9)
        // because these are rarely useful for items (min size 10).
        if post_residual > 0 && post_residual < 10 {
            score += 30.0;
        }

        // 4. Global state awareness: If we have many open bins, prioritize tightening existing ones.
        if open_bins_count > 5 {
            score += (open_bins_count as f64) * 0.5;
        }
    }

    // 5. Progression factor: As we near the end of the stream, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

