    // because the minimum item size is 1. We penalize small, unusable remainders.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead/Next-Item Coupling:
    // If next_item_size is large, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Strong reward for preserving compatibility for the next item
        } else {
            score += 10.0; // Penalty if current choice blocks the next item
        }
    }

    // 4. Thresholding/New Bin logic:
    // If we are forced into a new bin (bin_residual == bin_capacity), 
    // we should only do so if current open bins are "too full" to be efficient.
    if bin_residual == bin_capacity {
        // If there are open bins that could fit the item, penalize opening a new one heavily.
        if fitting_bins_count > 0 {
            score += 40.0;
        } else {
            // If no bins fit, opening a new one is neutral (score is 0 + capacity).
            score = 50.0; 
        }
    }

    // 5. Global state normalization:
    // Favor bins that align with the current mean residual to keep bin states uniform.
    let diff_from_mean = (post_residual as f64 - mean_residual).abs();
    score += diff_from_mean * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
