    // where the post_residual is too small to fit common small-to-medium items,
    // while biasing towards keeping the mean_residual high for future flexibility.

    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' (residuals < 10 are rarely useful for items >= 10)
    // We heavily penalize residuals that are non-zero but too small for the minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // Lookahead logic: if the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Harmonic load balancing: 
    // If we have many open bins, penalize opening a new one unless it's a perfect fit.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 35.0; // Discourage opening new bins early
        }
        // If the new bin is the only option or significantly better than existing, the penalty is offset by the perfect fit.
    }

    // If this is the last chance for the current item (fitting_bins_count == 1), 
    // we make it highly attractive to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Progression scaling: As we reach the end of the stream, prioritize closing bins (Best-Fit).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (mean_residual - post_residual as f64);

    score
}

