    // Base score is the residual space after placement.
    // Minimizing this usually corresponds to Best Fit.
    let mut score = post_residual as f64;

    // Penalty for creating "slivers" (very small unusable space).
    // If post_residual is < 10, it's likely dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Lookahead logic: If the next item fits into the current post_residual,
    // we prioritize this bin heavily to avoid leaving the next item stranded.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // Global state awareness: If we have many open bins, we should be more
    // aggressive in filling existing ones rather than opening new ones.
    if bin_residual == bin_capacity {
        // This is a new bin candidate. Penalize based on how many bins are already open.
        // As the stream nears the end, penalize opening new bins more heavily.
        score += (open_bins_count as f64 * 2.0) + (progress * 50.0);
    } else {
        // If this is the last chance to fit the item in an existing bin,
        // reward this bin to prevent opening a new one unnecessarily.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Heuristic adjustment: Favor bins that stay close to the global mean residual
    // to keep the bin distribution uniform.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // We aim to minimize waste (post_residual).
    // Penalize small residuals that are too small to fit common items (dead space).
    // The "best fit" heuristic is a strong baseline, but we modify it based on 
    // stream progression and lookahead potential.

    let mut score = post;

    // Penalty for creating a bin with very little space left if it's too small for most future items.
    // We treat residuals < 10 as "dead space" unless we are near the end of the stream.
    if post < 10.0 && post > 0.0 {
        score += 20.0 * (1.0 - progress);
    }

    // If this is a new bin (bin_residual == bin_capacity), penalize opening it 
    // unless the fit in existing bins is poor.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin is high, but decreases as we 
        // need to accommodate larger items that don't fit well elsewhere.
        score += 45.0 - (progress * 10.0);

        // If we have other bins that can fit the item, heavily penalize opening a new one.
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Lookahead influence: If the next item is large, favor keeping larger residuals open.
    // If post_residual is smaller than next_item_size, we might be creating a bin 
    // that won't be useful for the next step.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Influence of open_bins_count: discourage spreading items too thin.
    score += (open_bins_count as f64) * 0.5;

    // Adjust based on mean_residual to keep bins balanced.
    score += (post - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // 2. Harmonic Class logic: identify "dead zones" where post_residual is too small for common items
    // If post_residual is in [1, 9], it's dangerous because min item size is 10.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 3. Lookahead coupling: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than next_item_size, we create a bottleneck.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // 4. Thresholding: Avoid opening a new bin if an existing one can fit the item
    // unless the current fit is extremely inefficient.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 60.0; // Penalty for opening a new bin if current items can fit
        }
    }

    // 5. Global state normalization:
    // If we are nearing the end of the stream, prioritize tight packing (lower residuals).
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (post_residual as f64) * 0.5;
    }

    // 6. Harmonic balance: 
    // Penalize bins that deviate significantly from the mean residual of open bins.
    // This helps keep bins balanced in terms of remaining capacity.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If post_residual is in the range [1, 9], it is highly likely
    // to be unusable for future items (min size 10). Heavily penalize this "dangling" space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. Lookahead Synergy: If the next item can fit in the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bins Pressure: Penalize opening new bins (bin_residual == bin_capacity)
    // proportional to the number of bins already open to discourage fragmentation.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 2.5;
    }

    // 4. Tightness Optimization: Favor bins that leave a residual close to the mean_residual
    // to keep bin utilization balanced, but only if the bin is not being newly opened.
    if bin_residual < bin_capacity {
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    // 5. Last Chance Logic: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 6. Progression Scaling: As the stream nears the end, prioritize tight packing
    // more aggressively to close out existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize opening new bins unless the fit is perfect or necessary
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 1000.0; // Heavy penalty for opening new bins if others fit
        } else {
            score -= 50.0; // Bias towards starting a new bin if nothing else fits
        }
    }

    // 2. Lookahead optimization: If current fit leaves space for next_item_size, prioritize it.
    // We want post_residual to be as close to next_item_size as possible without going under.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect fit scenario: next item fits perfectly in the remaining space
            let diff = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 / (1.0 + diff));
        } else {
            // Dead space penalty: current fit makes it impossible to fit next_item_size
            score += 15.0;
        }
    }

    // 3. Density balancing: Encourage filling bins that are already below average fullness
    // (i.e., bins with higher residuals).
    if bin_residual < bin_capacity {
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score -= 0.5 * deviation;
    }

    // 4. Tightness constraint: Highly prioritize bins that become "near-full" (residual < 10)
    if post_residual < 10 {
        score -= 40.0;
    }

    // 5. Progression adjustment: As we reach the end of the stream, be more conservative
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
