    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
        // Further reward if it nearly fills the bin perfectly
        if (post_residual - next_item_size) < 5 {
            score -= 20.0;
        }
    }

    // 3. Global Density Management: If we have many open bins, push for tighter packing.
    // As progress increases, become more aggressive in closing open gaps.
    let density_penalty = (open_bins_count as f64) * (1.0 + progress);
    score += density_penalty;

    // 4. New Bin Threshold: Discourage opening a new bin unless the current residual is very poor.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin
        score = 45.0;

        // If we are near the end of the stream, prioritize using existing bins.
        if progress > 0.8 {
            score += 50.0;
        }

        // If only one bin can fit the item, opening a new one is highly discouraged.
        if fitting_bins_count > 0 {
