    let mut score = post_res;

    // Penalty for creating "dead space": if post_residual is in the 1-9 range, 
    // it's likely to be unusable for future items (min size 10).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 - (post_res / 10.0));
    }

    // Lookahead logic: if next item is large, avoid leaving small residuals now.
    if next_item_size > 60 {
        score += (100.0 - post_res) * 0.5;
    }

    // Dynamically discourage opening new bins as the stream nears completion
    // to force consolidation, unless the fit is exceptionally bad.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 40.0);
    }

    // Encourage balance: if fitting_bins_count is low, prefer bins that bring
