    if fitting_bins_count > 0 {
        let deviation = (post_res - mean_residual).abs();
        score -= deviation * 0.2;
    }

    // Penalize high open_bins_count to encourage packing density
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize large post-residuals to favor tight packing.
    // We use a quadratic penalty on post_residual to discourage leaving large gaps.
    score += (post_residual as f64).powi(2) * 0.05;

    // 2. Harmonic Lookahead: If next_item_size is known, favor bins that can accommodate it.
    // If post_residual is slightly less than next_item_size, it's a "bad" gap (dead space).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 45.0;
        } else {
            // Reward bins that leave exactly enough or just enough room for the next item.
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // 3. Last Chance Logic: If this is the only bin that fits the item, prioritize it highly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // 4. New Bin Thresholding: Discourage opening a new bin unless the fit is extremely poor.
    // If bin_residual == bin_capacity, we are evaluating a new bin.
    if bin_residual == bin_capacity {
        // Only open a new bin if the average residual of existing bins is already small (< 20).
        // If existing bins are mostly full, opening a new one is efficient.
        if mean_residual > 20.0 {
            score += 30.0; 
        } else {
            score += 55.0; 
        }
    }

    // 5. Progression Scaling: As the stream nears the end, become more aggressive 
    // in packing items into fewer bins to avoid stranded items.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
