    if bin_residual == bin_capacity {
        // This is the "New Bin" candidate.
        // Penalize opening a new bin proportionally to the number of existing open bins.
        score += (open_bins_count as f64) * 15.0;

        // If we have many bins open, but they are mostly empty (high mean_residual), 
        // we should favor using an existing one rather than opening a new one.
        if mean_residual > 40.0 {
            score += 40.0;
        }
    } else {
        // If this is an existing bin, reward configurations that keep the residual 
        // close to the mean to maintain bin uniformity.
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.2;
    }

    // 4. Scarcity: If this is the only bin that can fit the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 5. Progression: As the stream nears completion, become more aggressive about filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
