pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the post-placement residual. 
    // Best-Fit strategy typically likes smaller residuals (higher values here).
    // We want to minimize the score, so we prioritize bins that leave the LEAST space.
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // Only open a new bin if the current fit is extremely poor (post_residual is large)
    // or if we are nearing the end of the stream and need to clear space.
    if is_new_bin {
        if fitting_bins_count == 0 {
            score = 50.0; // Forced move
        } else {
            // High penalty for opening a new bin if we have fits available.
            // Scale penalty by how much space we waste by not using existing bins.
            score = 150.0 + (mean_residual * 2.0);
        }
    } else {
        // Reward bins that leave space for the next item (Lookahead optimization)
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }

        // Penalty for creating "dead space" (e.g., leaving 1-9 units)
        // because these are very hard to fill later.
        if post_residual > 0 && post_residual < 10 {
            score += 40.0 * (1.0 - progress);
        }

        // Global pressure: if we have many open bins, prioritize tightening existing ones.
        score += (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    // Penalize small residuals that are likely to become "dead space" (e.g., < 10 units).
    let mut score = post_res;

    if post_res < 10.0 && post_res > 0.0 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: If the next item is large, prioritize bins that can accommodate it.
    // We penalize bins that leave a post_residual too small for the next item.
    if next_item_size > 0 {
        if post_res < next_item_size as f64 {
            score += 15.0 * (1.0 - (post_res / 100.0));
        }
    }

    // New Bin Penalty: Heavily penalize opening a new bin early in the stream, 
    // but allow it if the current bin's mean_residual is already very low (fragmentation).
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress);
        score -= (mean_residual * 0.2); 
    }

    // Fitting Bins Constraint: If this is the only bin that fits the item, 
    // prioritize it heavily to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Coupling: Reward filling bins to near-capacity as the stream progresses (End-game optimization).
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= (fill_ratio.powf(2.0) * 10.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Penalize configurations that create "slivers" (unusable space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Harmonic Class Logic: Favor residuals that are multiples of common item sizes (e.g., 20, 25, 33)
    // This helps align future items into the remaining space.
    let harmonic_alignment = (post_residual % 20) as f64;
    score += harmonic_alignment * 0.5;

    // 3. Lookahead Synergy: If the next item fits perfectly into the remaining space, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_tightness = (post_residual - next_item_size) as f64;
        score -= (100.0 - fit_tightness) * 0.8;
    }

    // 4. Global State Awareness: If we are near the end of the stream, be more aggressive with packing
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    // 5. New Bin Thresholding: 
    // If bin_residual == bin_capacity, we are evaluating opening a new bin.
    // We only want to open a new bin if the mean residual of current bins is high (i.e., they are poorly packed)
    // or if we are forced to (fitting_bins_count == 0).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0; // Forced, make it attractive
        } else {
            // Only open a new bin if the average space already wasted is significant
            score += mean_residual * 0.5;
        }
    } else {
        // Discourage picking a bin that is almost empty if other options exist
        if bin_residual > 90 {
            score += 15.0;
        }
    }

    score
}

