    };

    // Objective: Minimize post_residual (Best Fit), but penalize creating "dead zones"
    // (bins with very small residuals that are unlikely to fit future items).
    // We use a non-linear penalty for residuals < 10 (hard to fill)
    let dead_zone_penalty = if post_residual > 0 && post_residual < 10 {
