    // the distribution of bin fullness uniform across the set.
    let mean_alignment = (post_res - mean_residual).abs() * 0.1;

    // Final score: lower is better
    let score = post_res + new_bin_penalty + dead_zone_penalty + lookahead_bonus + mean_alignment;

