    // 2. Best-fit logic: Reward smaller post_residual (Best Fit)
    // We already start with post_residual as the score, which encourages tight packing.

    // 3. Lookahead Logic: If the next item fits perfectly into the current post_residual, 
    // reward this bin significantly (Best-Fit-Lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward if the remaining space is a "near-perfect" match for the next item
            let gap = (post_residual - next_item_size) as f64;
            score -= (10.0 / (1.0 + gap));
        } else {
            // Penalize if the post_residual is now useless for the next item
            score += 5.0;
        }
    }

    // 4. Global Density Control: 
    // If the mean residual is high, we are being too loose; prioritize filling bins 
    // that are currently further from the mean to tighten the pack.
    let dev_from_mean = (bin_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.1;

    // 5. Urgency: If this is the only bin that can fit the item, prioritize it 
    // to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Progress Scaling: As the stream nears completion, become more aggressive 
    // about closing bins (higher penalty for opening new ones).
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
