        if post_residual == next_item_size { score -= 20.0; }
    }

    // 4. New Bin Thresholding: Penalize opening a new bin unless the current
    // fitting options are extremely poor (i.e., they create high-fragmentation residuals).
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already or if the average 
        // quality of existing bins is very poor (high mean_residual).
        score += (open_bins_count as f64 * 2.0) + (mean_residual * 0.5);
    } else {
        // If this bin is a perfect fit, reward it to prevent opening new bins unnecessarily.
        if post_residual == 0 {
