    // Penalize small residuals (fragmentation) non-linearly.
    // The "Best Fit" behavior is promoted by the quadratic term of post_residual.
    let fragmentation_penalty = if post < 15.0 {
        (15.0 - post).powf(2.5) * 2.0
    } else {
        0.0
    };

    // Lookahead logic: if the next item is large and fits into current post_residual, 
    // reward keeping space available.
    let lookahead_benefit = if next_item_size > 0 && (post_residual >= next_item_size) {
        -((post_residual - next_item_size) as f64).sqrt() * 5.0
    } else {
        0.0
    };

    // Global state awareness: 
    // As the stream progresses, prioritize closing bins (lower open_bins_count).
    // Penalize opening a new bin (bin_residual == bin_capacity) more as we near the end.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        (fitting_bins_count as f64 * 50.0) + (progress * 100.0)
    } else {
        0.0
    };

    // Balance mean residual: avoid bins that deviate too far from the average load
    let mean_deviation = (post_residual as f64 - mean_residual).abs() * 0.5;

    let score = post + fragmentation_penalty + lookahead_benefit + new_bin_penalty + mean_deviation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
