    }

    // 3. Harmonic class alignment: Favor filling bins to capacity or half-capacity (50).
    // This rewards placements that result in residuals near 0 or 50.
    let dist_to_ideal = ((post_residual as f64 - 50.0).abs()).min(post_residual as f64);
    score += dist_to_ideal * 0.2;

    // 4. If this is the only bin that fits, we are forced to use it; minimize penalty.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Penalize opening a new bin (bin_residual == bin_capacity) unless residuals are already poor.
    // We scale this penalty by the number of open bins to encourage consolidation.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.0);
    }

    // 6. Dynamic pressure: As the stream progresses, favor tighter packing to avoid a late-game bin explosion.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    score
}

