    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 2.0;
    }

    // New Bin Logic: Only open a new bin if the current options are extremely poor.
    // If this is a new bin, we penalize it based on how many bins are already open 
    // and how well the current item fits into existing ones.
    if bin_residual == bin_capacity {
        score += 40.0;
        score += (open_bins_count as f64) * 5.0;
        score -= (fitting_bins_count as f64) * 15.0;
    }

    // Balance the mean residual: discourage bins that deviate significantly 
    // from the average efficiency of the current open set.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize tighter fits (smaller post_residual)
    let mut score = post * post;

    // Penalty for leaving "dead space" that cannot fit common items
    // If post_residual is small but > 0, it's often more wasteful than a slightly larger residual.
    // We heavily penalize the [1, 9] range as it creates unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: If next_item_size is large, favor bins that can accommodate it.
    // If next_item_size is 0 (end of stream), prioritize closing bins (lower post_residual).
    if next_item_size > 0 {
        let next_fit_penalty = if post_residual >= next_item_size {
            -150.0 * (next_item_size as f64 / 100.0)
        } else {
            100.0 * (next_item_size as f64 / 100.0)
        };
        score += next_fit_penalty;
    }

    // Dynamic thresholding: As the stream progresses, become more aggressive in 
    // filling existing bins to minimize open_bins_count.
    // We penalize opening new bins (bin_residual == bin_capacity) more as progress increases.
    if bin_residual == bin_capacity {
        score += 250.0 + (progress * 300.0);
    } else {
        // Encourage balanced usage across open bins by penalizing deviation from mean_residual
        let deviation = (bin_residual as f64 - mean_residual).abs();
        score += deviation * 2.0;
    }

    // Interaction term: If this is the only bin that fits the item, make it highly attractive.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
