    }

    // 2. Harmonic Class Logic: Prefer filling to specific thresholds (e.g., 0, 25, 50).
    // Penalize residuals that fall into "awkward" gaps.
    let remainder = post_residual % 25;
    score += remainder as f64 * 0.5;

    // 3. Lookahead Logic: If next_item_size is large, avoid small post_residuals.
    if next_item_size > 0 {
