            score -= (next_item_size as f64) * 0.4;
        }
    }

    // 4. Global State Awareness:
    // If we have many open bins, prioritize tighter packing (lower post_residual).
    // If we have few open bins, be more permissive.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64 * 0.1) * (1.0 - progress);

    // 5. New Bin Logic:
    // If bin_residual == bin_capacity, this is a new bin. 
    // Only choose a new bin if the cost of existing bins is significantly higher.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin is related to how well we fit in existing bins.
        // If fitting_bins_count is high, we should rarely open a new bin.
        score = 80.0 + (fitting_bins_count as f64 * 15.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
