    } else if post_residual < 10 {
        score -= 5.0;  // Reward for near-perfect packing
    }

    // 2. Lookahead matching: If next_item_size fits in post_residual, drastically lower the score.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Further reward if the second item fits perfectly
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // 3. Prevent fragmentation: If post_residual is in the "dead zone" (too small for most items), penalize.
    // Assuming typical item sizes are 10+, any residual < 10 is likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // 4. Global distribution awareness:
    // If we have many open bins, penalize opening a new one (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 35.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 5. Fitting constraint awareness:
