    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize residuals that are too small to fit typical future items (e.g., < 10)
    // but not zero. These are "orphaned" gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
