    // 2. Lookahead Synergy: If the next item fits into the current post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Bin Pressure: If this is the only bin that can fit the item, prioritize it to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 4. Global Efficiency: Penalize opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;
