        score += (step_index as f64 / total_items as f64) * 20.0;
    }

    // 5. Mean Residual Alignment: Reward bins that stay close to the average usage to keep packing uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual to keep bins tight.
    // We prioritize bins that leave very little space (Best-Fit principle).
