    // 2. Lookahead matching: If post_residual is close to next_item_size, we reward this bin.
    // The goal is to perfectly fill the bin with the next incoming item.
    if next_item_size > 0 {
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;
        score -= 50.0 / (1.0 + diff);
    }

    // 3. Fragmentation Penalty: Penalize bins that deviate significantly from the mean usage.
    // This keeps bin residuals uniform, reducing the chance of creating "dead" bins.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.5;

    // 4. New Bin Threshold: Discourage opening a new bin unless the fit is extremely poor.
    // If we have open bins that can fit the item, we penalize the "new bin" candidate (bin_residual == bin_capacity).
    if bin_residual == bin_capacity && open_bins_count > 0 {
