    }

    // 5. Last Chance Heuristic: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // 6. Progressive tightening: As the stream nears completion, become more aggressive 
    // about filling existing bins to avoid leaving stragglers.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
