pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Penalize creating "dead space" that is too small for common future items (below 10),
    // but reward configurations that pack tightly.
    // We use a non-linear penalty for small post_residuals that are likely to be wasted.
    let waste_penalty = if post_res < 10.0 && post_res > 0.0 {
        (10.0 - post_res) * 5.0
    } else {
        0.0
    };

    // Lookahead logic: if next_item_size is large, favor leaving more room in the current bin
    // if it helps accommodate the next item, or pack tightly if it's small.
    let lookahead_adj = if next_item_size > 0 {
        if post_res >= next_item_size as f64 {
            -15.0 * (next_item_size as f64 / 100.0)
        } else {
            10.0 * (next_item_size as f64 / 100.0)
        }
    } else {
        0.0
    };

    // Global strategy: Toward the end of the stream, prioritize packing tightly into existing bins
    // to avoid opening new ones, heavily penalizing new bin creation.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        40.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Factor in the mean residual: discourage bins that deviate significantly from the 
    // average efficiency to keep bin states uniform.
    let uniformity_penalty = (post_res - mean_residual).abs() * 0.5;

    // Final score: minimize post_residual (Best Fit), but adjust for future needs and stream state.
    let score = post_res 
        + waste_penalty 
        + lookahead_adj 
        + new_bin_penalty 
        + uniformity_penalty;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
