        score -= (next_item_size as f64) * 2.5;
        // Further bonus if the post_residual is nearly perfectly filled by the next item.
        let diff = (post_residual - next_item_size) as f64;
        score -= (100.0 - diff) * 0.5;
    }

    // 3. New-bin thresholding: Discourage opening a new bin unless the current 
    // mean_residual is very high (indicating existing bins are mostly empty).
    if bin_residual == bin_capacity {
        // High penalty to open a new bin if other bins exist with decent space.
        if open_bins_count > 0 {
            score += 150.0 + (mean_residual * 2.0);
        }
    } else {
        // Penalty for leaving a very small, unusable slice (e.g., 1-5 units)
        if post_residual > 0 && post_residual < 8 {
            score += 40.0;
        }
    }

    // 4. Progress awareness: In the late stages of the stream, prioritize closing 
    // bins over keeping them open.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= (1.0 - progress) * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual: Prefer bins that leave little space (Best Fit intuition).
    // penalty: Penalize creation of "dead space" (e.g., leaving 1-9 units).
    // lookahead: If next_item_size fits in post_residual, prioritize this bin.
    // global: Penalize opening new bins unless the current options are very poor.

    let mut score = post_residual as f64;

    // 1. Penalize creating "fragmented" space (1..9 units are usually unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

