    // 3. Dynamic Thresholding: Penalize opening a new bin (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean_residual of existing bins is already very low (crowded).
        // If mean_residual is high, we should favor existing bins.
        score += 30.0 + (100.0 - mean_residual);
