    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize near-empty bins
    // to encourage packing tightly (Best-Fit principle).
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead Integration: If the next item fits into the current post_residual, 
    // prioritize this bin to maximize bin utilization (Best-Fit Decreasing logic).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 2.5;
    }

    // 3. Dynamic Thresholding: As the stream progresses, increase pressure to 
    // close bins by penalizing the creation of new bins (if bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 + progress);
        // If we have many open bins already, penalize opening another one further.
        score += (open_bins_count as f64) * 5.0;
    }

    // 4. Dead Space Avoidance: Penalize leaving small gaps that are unlikely to be filled.
    // Gaps between 1 and 9 are statistically hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 5. Global State Balancing: If this bin is the last chance for the current item,
    // reduce its penalty to ensure we don't open a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Mean Residual Weighting: Avoid bins that deviate too far from the average
    // residual to keep the distribution of bin fullness uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    // We aim to minimize this (Best Fit)
    let mut score = post;

    // Penalty for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), apply a dynamic barrier.
    // As the stream progresses, the penalty for opening a new bin increases to force consolidation.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 50.0);
    } else {
        // Reward bins that bring the residual closer to the mean residual of other bins
        // This encourages balancing the load across open bins.
        let deviation = (post - mean_residual).abs();
        score += 0.5 * deviation;

        // Lookahead heuristic: If the next item is large, penalize small residuals in this bin
        // to keep space open for the upcoming item.
        if next_item_size > 0 {
            if post < next_item_size as f64 {
                score += (next_item_size as f64 - post) * 1.5;
            }
        }
    }

    // Criticality: If this is the only bin that can fit the item, prioritize it heavily
    // to avoid unnecessary bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize extreme fragmentation: if post_residual is very small (e.g., < 10),
    // it likely creates "dead space" that cannot fit future items.
    if post < 10.0 && post > 0.0 {
        score += (10.0 - post) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

