    // 4. New Bin Logic: Discourage opening a new bin unless the current fit is terrible.
    // If we are looking at an empty bin (new bin candidate)
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if other options exist, unless the current state is stagnant.
            score += 60.0 + (open_bins_count as f64 * 2.0);
        }
    }

    // 5. Global state normalization:
    // If we are nearing the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 50.0;
    }

    // 6. Mean residual balancing:
    // If this bin's residual is significantly better than the global mean, favor it.
    if (post_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
