        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 5. Global Efficiency: If the bin is becoming very full, reward it to 
    // favor "closing" bins effectively.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (small residuals that cannot fit common items).
    // If the post_residual is less than 10, it's often a wasted sliver.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 2.0);
    }

    // 2. Aggressive 2-step lookahead matching:
    // If the next item fits perfectly into the post_residual, prioritize this bin heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 / (1.0 + diff));
    }

    // 3. Balancing: If this is the only bin that fits the current item, 
    // force selection (reduce score) to avoid opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 4. Global state awareness:
    // If we are late in the stream, favor filling bins tighter to minimize tail fragmentation.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.5);

    // 5. If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless we have no other choice (i.e., fitting_bins_count == 0).
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 60.0;
    }

    // 6. Prefer bins that are closer to the current mean_residual to keep 
    // the packing density uniform across all active bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best Fit Decreasing logic: penalize creating large gaps.
    // We prefer post_residual to be as small as possible (Best Fit).
    score += (post_residual as f64).powf(1.2);

    // 2. Lookahead optimization: 
    // If the next item is large, avoid bins that would be left with a tiny, unusable gap.
    if next_item_size > 0 {
        let post_post_residual = post_residual as i32 - next_item_size as i32;
        if post_post_residual >= 0 {
            // Reward bins that can accommodate the next item perfectly.
            score -= (100.0 - post_post_residual as f64) * 0.5;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Penalize bins that would "waste" the next item's potential fit.
            score += 25.0;
        }
    }

    // 3. Fragmentation control:
    // If this is the only bin that can fit the item, prioritize it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 4. Global State awareness:
    // If many bins are open, be more aggressive about packing tightly (Best Fit).
    // If few bins are open, allow more slack to keep future options flexible.
    let density_pressure = (open_bins_count as f64 / (1.0 + (100.0 - mean_residual))) * 10.0;
    score += density_pressure;

    // 5. Dynamic Time Horizon:
    // As we approach the end of the stream, prioritize closing bins over opening new ones.
    if progress > 0.9 {
        if bin_residual == bin_capacity {
            score += 200.0; // Heavy penalty for opening new bins near end
        }
    }

    // 6. New Bin Penalty:
    // Always apply a base penalty for opening a fresh bin to enforce Best Fit.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize empty bins increasingly as the stream progresses to discourage new bins
    // unless the fit is exceptionally poor (Best Fit Decreasing logic).
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_penalty = if is_new_bin {
        45.0 + (55.0 * progress.powf(0.5))
    } else {
        0.0
    };

    // Calculate a "tightness" factor: we want to keep post_residual small, 
    // but avoid values that are too small to fit future items (the 10-20 range).
    // If post_residual is in (0, 10), it's often wasted space.
    let waste_penalty = if post < 10.0 && post > 0.0 {
        25.0 * (1.0 - (post / 10.0))
    } else {
        0.0
    };

    // Use lookahead: if next_item_size is large, prefer leaving a larger post_residual.
    let lookahead_mod = if next_item_size > 0 {
        let diff = (next_item_size as f64 - post).max(0.0);
        diff * 0.5
    } else {
        0.0
    };

    // Favor bins that are already "half-full" (mean_residual interaction)
    // to keep the number of active bins consolidated.
    let consolidation_bonus = (mean_residual - post).abs() * 0.1;

    let mut score = post + new_bin_penalty + waste_penalty + lookahead_mod - consolidation_bonus;

    // If this is the only bin that can fit the item, strongly prioritize it
    // to avoid the new_bin_penalty.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #1156: Harmonic-Residual Coupling
    // Objectives: 
    // 1. Minimize post_residual (Best Fit).
    // 2. Penalize "near-miss" residuals that are too small to fit common items (10-30).
    // 3. Favor bins that can accommodate the next item (Lookahead).
    // 4. Dynamically penalize new bin creation based on current density (mean_residual).

    let mut score = post_residual as f64;

    // Penalty for creating a "dead zone" (residual too small to fit most items)
    // We penalize post_residual ranges [1, 9] heavily as they are rarely useful.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: If the next item fits into the current post_residual, 
    // prioritize this bin significantly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // New Bin Logic: Discourage opening a new bin unless the existing bins are highly fragmented.
    // If bin_residual == bin_capacity, it's a new bin candidate.
    if bin_residual == bin_capacity {
        // Only open new if the mean residual of existing bins is already very low (high fragmentation)
        // or if we are forced to (fitting_bins_count == 0).
        if fitting_bins_count > 0 {
            // Heuristic penalty to prevent premature new bin creation
            score += 40.0 + (mean_residual * 0.5);
        }
    }

    // Harmonic class adjustment:
    // Favor residuals that align with the capacity/item ratio to minimize wasted space.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Progression scaling: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
