    // Penalize creating tiny, unusable gaps (1-9) which are often "dead space".
    // We heavily penalize small post_residuals if we are near the end of the stream.
    let dead_space_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * (1.0 + progress * 5.0)
    } else {
        0.0
    };

    // Reward bins that are nearing capacity (Best Fit principle).
    // The exponent 1.5 makes the scoring non-linear, favoring tighter packs.
    let tightness_reward = (bin_capacity as f64 - post).powf(1.5) * 0.1;

