pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the remaining space (Best Fit principle).
    let mut score = post;

    // Penalty for creating "dead space" (residuals < 10 are often unusable for most items).
    // The penalty is non-linear and scales with the progression of the stream.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powf(2.0) * (1.0 + progress);
    }

    // Reward bins that can accommodate the lookahead item (next_item_size).
    // If post_residual is >= next_item_size, we favor this bin to keep fragmentation low.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * (1.0 - progress * 0.5);
    }

    // If this is the only bin that fits the current item, avoid opening a new bin
    // unless the fit is extremely poor (large residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0; 
    }

    // Dynamic pressure: As the stream progresses, favor packing tighter (lower mean_residual).
    // We penalize bins that have a residual significantly higher than the current mean.
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * progress;
    }

    // If evaluating a new bin (bin_residual == bin_capacity), apply a heavy penalty
    // that decreases slightly as the stream nears the end to allow for final cleanup.
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress * 0.2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins with smaller post_residual (minimize waste).
    // The base score is already post_residual, so we refine it.

    // 2. Penalty for creating "sliver" space: if post_residual is < 10, it's often unusable.
    // We penalize very small residuals that aren't zero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Logic: If next_item_size is known, try to leave room for it.
    // If post_residual is smaller than the next item, we effectively block that bin for that item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // 4. Harmonic/Modulo adjustment: favor residuals that are multiples of common item sizes (e.g., 20, 25, 50).
    // This helps keep bins "clean" for future items.
    if post_residual % 20 == 0 {
        score -= 5.0;
    }

    // 5. New Bin Logic: If this is an empty bin (new bin candidate)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very low (bins are full)
        // or if we have no other good options.
        if fitting_bins_count > 0 {
            // Penalize opening a new bin if we have existing bins that can fit the item
            score += 40.0 + (mean_residual * 0.5);
        } else {
            // If no fitting bins, prioritize opening a new one
            score = 0.0;
        }
    }

    // 6. Progressive threshold: as we approach the end of the stream, be more aggressive
    // about filling existing bins to avoid leftover items.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
