    // Stream progression adjustment: As we reach the end of the stream, 
    // prioritize closing existing bins (reducing open_bins_count) over creating new ones.
    // We penalize opening new bins (bin_residual == bin_capacity) more heavily as progress increases.
    if bin_residual == bin_capacity {
