    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 100.0;
    }

    // 5. New Bin Constraint:
    // If we are considering a new bin (bin_residual == bin_capacity), make it expensive 
    // unless the current open bins are all very poor fits.
    if bin_residual == bin_capacity {
        score += 45.0;
        // As the sequence progresses, become more conservative about opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit Penalty: Minimize post_residual, but heavily penalize "sliver" space (1-9)
    // which is hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Lookahead Integration: If the next item fits into the current post_residual,
    // reward this bin to keep the next item compact.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    }

    // 3. Global State Balancing: If we have many open bins, prioritize filling existing ones
    // to keep open_bins_count low, especially as we near the end of the stream.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64) * 0.5;
        score -= (1.0 - progress) * 20.0;
