    // 4. New Bin Thresholding: Discourage opening a new bin unless the current residual
    // is truly terrible for the incoming item.
    if bin_residual == bin_capacity {
        // If there are bins that can fit the item, only open a new one if necessary.
        if fitting_bins_count > 0 {
            score += 60.0 + (mean_residual * 0.5);
        } else {
            score -= 10.0;
        }
    }

    // 5. Density heuristic: Favor bins that stay near the mean_residual to maintain
    // consistency across all active bins.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post-placement residual (Best-Fit principle).
    // Penalize small residuals (fragmentation) by introducing an exponential decay term.
    // As progress increases, we become more conservative (tighter packing required).
    let fragmentation_penalty = (100.0 - post).exp() / 100.0;

    // Incorporate lookahead: if next_item_size fits in the current post_residual, 
    // heavily reward this bin.
    let lookahead_reward = if next_item_size > 0 && next_item_size <= post_residual {
        -50.0 * (1.0 - progress)
    } else {
        0.0
    };

    // If this is a new bin (bin_residual == bin_capacity), calculate a dynamic cost.
    // Discourage opening new bins early in the stream, but allow it if existing 
    // bins are heavily fragmented (mean_residual is low).
    let new_bin_cost = if bin_residual == bin_capacity {
        let base_new_bin = 45.0 + (progress * 20.0);
        let urgency = (1.0 - (mean_residual / bin_capacity as f64)) * 30.0;
        base_new_bin - urgency
    } else {
        0.0
    };

    // Penalize bins that are "last chance" if they result in high fragmentation,
    // to force better usage of bins that still have room for future items.
    let scarcity_penalty = if fitting_bins_count == 1 && post > 20.0 {
        15.0 * (1.0 - progress)
    } else {
        0.0
    };

    post + fragmentation_penalty + lookahead_reward + new_bin_cost + scarcity_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Perfect fit bonus: heavily reward placing items that leave no space
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2. Harmonic class logic: penalize small remainders that cannot fit typical items (10-30)
    // If the post_residual is in the "dead zone" (between 1 and 9), we penalize it.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 / (post_residual as f64 + 0.1);
    }

    // 3. Lookahead integration: prioritize bins that can accommodate the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0;
        } else {
            // Penalize creating a bin that cannot fit the next item if we have other choices
            score += 15.0;
        }
