    // 4. New bin management: restrict opening new bins unless the fit is extremely poor
    if bin_residual == bin_capacity {
        // Only open a new bin if the current open bins are very full (mean_residual is low)
        // or if fitting_bins_count is 0 (which is always true for a new bin by definition)
        if mean_residual > 20.0 {
            score += 100.0; // High penalty for opening new bins prematurely
        } else {
            score += 40.0; // Moderate penalty
        }
    }

    // 5. Density heuristic: favor filling bins that are already partially full
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // 6. Progression scaling: as the stream nears the end, be more aggressive with space
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
