    // We dynamically scale the cost of opening a new bin based on progress and 
    // the number of bins already in use to discourage fragmentation early.
    if bin_residual == bin_capacity {
        score += 35.0 + (progress * 25.0) + (open_bins_count as f64 * 0.5);
    } else {
        // Reward placements that align with the mean residual to keep bin fill levels uniform.
        // This reduces the variance of residuals, preventing "stranded" small items.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.2;

        // Lookahead heuristic: If we know the next item, penalize leaving a post_residual 
        // that is too small for the next item, unless it fits perfectly (post == 0).
        if next_item_size > 0 && post > 0.0 {
            if (post as u32) < next_item_size {
                score += 15.0 * (1.0 - progress);
