    }

    // Criticality adjustment: If this is the only bin that can fit the item, 
    // heavily reward choosing it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Non-linear interaction: Penalize tight fits (post near 0) slightly if we are 
    // early in the stream, to reserve them for potentially larger items later.
    if post < 5.0 && progress < 0.3 {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
