pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // post_residual: smaller is better (Best Fit).
    let mut score = post_residual as f64;

    // Penalty for creating "dead zones" (small residuals that cannot fit common items).
    // If post_residual is < 10, it is likely wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: If the next item fits into this post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Dynamic thresholding: If we are near the end of the stream, prioritize tight packing.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score += (post_residual as f64) * 0.5;
    }

    // Global state awareness: If this is the only bin that can fit the item, 
    // prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin (bin_residual == bin_capacity) unless residuals are poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 35.0;
        // If there are many open bins, penalize opening another one even more.
        score += (open_bins_count as f64) * 2.0;
    }

    // Encourage keeping residuals close to the global mean to maintain bin consistency.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_res;

    // Penalize creating "fragmented" bins (small residuals that likely won't fit future items)
    // We add a penalty term that is high when post_residual is small but > 0
    if post_residual > 0 && post_residual < 15 {
        score += 25.0 * (1.0 - (post_res / 15.0));
    }

    // Lookahead logic: if the next item is large, favor bins that leave enough room for it
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding for opening new bins:
    // As the stream progresses, become more conservative about opening new bins
    // if the current bin is empty, assign a baseline cost that increases with progress
    if bin_residual == bin_capacity {
        score = 30.0 + (25.0 * progress);
    }

    // Coupling with mean_residual:
    // If this bin is significantly worse than the average, penalize it
    if post_res > mean_residual {
        score += (post_res - mean_residual) * 0.5;
    }

    // Reward bins that have high occupancy (low post_residual) as the stream nears the end
    score -= (1.0 - post_res / bin_capacity as f64) * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Penalty for creating 'fragmented' space (small, unusable residuals)
    // We penalize residuals that are smaller than the smallest likely item (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - (post_residual as f64 * 5.0);
    }

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is too small to fit the lookahead, add a penalty.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // If this is the only bin that fits, prioritize it heavily (Best Fit principle)
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // If we are considering a new bin, apply a threshold penalty to prevent premature bin opening.
    // We only open a new bin if the current fit is extremely poor (post_residual < 5).
    if is_new_bin {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // High penalty for opening a new bin unless the existing bins are nearly full
            score = 100.0 + (mean_residual * 0.5);
        }
    }

    // Harmonic/Modulo bias: favor residuals that align with common item sizes (e.g., 20, 25, 33, 50)
    // This helps in 'packing' patterns by aligning remaining space with potential future inputs.
    let harmonic_bias = (post_residual % 20) as f64;
    score += harmonic_bias * 0.2;

    // Progression weight: as we approach the end of the stream, be more conservative with new bins
    let progress = step_index as f64 / total_items as f64;
    if is_new_bin {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize small gaps that are unlikely to fit future items.
    // If post_residual is in (0, 10), it is highly likely to be wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item fits into the current bin's post_residual, 
    // prioritize this bin to preserve the packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // 3. Open Bin Pressure: Discourage opening new bins unless necessary.
    // If this is a new bin (bin_residual == bin_capacity), apply a penalty based on 
    // the count of currently open bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 5.0;

        // If there are other bins that can fit the item, strongly discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 100.0;
        }
    }

    // 4. Global Density Balancing: Prefer bins that align with the mean_residual 
    // to maintain uniform fragmentation across the bin set.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.5;

    // 5. Progression weighting: As the stream nears completion, become more aggressive 
    // about closing bins by penalizing large post_residuals more heavily.
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: penalize large post_residuals (wasted space)
    // 2. Penalty for opening a new bin if an existing bin could fit the item well
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 150.0; // Strong penalty for opening new bin if others can fit
        }
        score += 20.0; // Base cost for opening any new bin
    }

    // 3. Lookahead Matching (The "Tight Fit" optimization)
    // If the next item can fit perfectly or near-perfectly into the current post_residual,
    // reward this placement to keep the bin highly utilized.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Reward placements that leave exactly enough space for the next item
            score -= (50.0 / (gap + 1.0));

            // If the post_residual is very small (e.g., < 5), it's likely "dead space" 
            // unless it matches the next item perfectly.
            if post_residual < 5 {
                score += 10.0;
            }
        }
    }

    // 4. Mean Residual Balancing
    // Encourage filling bins that are already below the current mean_residual 
    // to consolidate items and prevent fragmented capacity.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // 5. Progression Scaling
    // As we approach the end of the stream, prioritize aggressive packing 
    // to minimize the number of bins left open.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating 'dead space' (small residuals that are hard to fill)
    // Residuals < 10 are generally useless given item size constraints
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead logic: if next item fits in the current post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Global state awareness: If we are near the end of the stream, prioritize 
    // filling existing bins over opening new ones.
    if is_new_bin {
        score += 40.0 * (1.0 - progress);

        // If there are other bins that could fit this item, penalize opening a new one
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Balance the load: if the current bin's residual is significantly lower than 
    // the mean residual of all open bins, it's a good place to put items (keep bins uniform)
    if !is_new_bin && (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Final adjustment: heavily discourage opening new bins if we have many open bins
    // that are already mostly empty (high mean_residual)
    if is_new_bin && mean_residual > 40.0 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post-residual space.
    // We aim to minimize this (Best Fit principle).
    let mut score = post;

    // Penalty for "fragmentation": If we leave a small residual that is likely unusable,
    // we penalize it more heavily as the stream progresses.
    // A residual < 10 is often "dead space" because min item size is 10.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 5.0 * (1.0 + progress);
    }

    // Heuristic: If we have multiple bins that can fit the item, prioritize the one
    // that balances the residual space relative to the average residual of open bins.
    // This keeps the packing density uniform.
    let residual_diff = (post - mean_residual).abs();
    score += residual_diff * 0.5;

    // Lookahead: If the next item is large, avoid leaving a tiny residual that 
    // forces the next item into a new bin.
    if next_item_size > 0 {
        if post > 0.0 && post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 2.0;
        }
    }

    // New bin logic:
    // If bin_residual == bin_capacity, this is the "New Bin" candidate.
    // We penalize opening a new bin heavily unless the current open bins are 
    // highly fragmented (high mean_residual) or we are near the end of the stream.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin is high.
        score = 80.0 + (mean_residual * 0.2);

        // As the stream progresses, the cost of opening a new bin decreases slightly 
        // to prevent forcing items into sub-optimal tight fits at the end.
        score -= progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: Penalize large residual space
    // We favor bins where post_residual is small (tight fit)
    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If next_item_size fits in the post_residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Harmonic Waste Penalty: Penalize post_residuals that are useless for common item ranges.
    // If post_residual is > 0 but < 10, it's "dead space" because min item size is 1.
    // We treat residuals < 10 as high-penalty zones unless they are exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 - (post_residual as f64);
    }

    // 4. New Bin Thresholding: 
    // If this is a new bin (bin_residual == bin_capacity), only pick it if open bins are insufficient.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing one can accommodate the item
            score += 150.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no existing bin fits, normalize the cost of opening a new one
            score -= 10.0;
        }
    }

    // 5. Mean Residual Balancing:
    // Avoid creating bins that deviate significantly from the current mean state
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.2;

    // 6. Progressive packing: As we approach the end of the stream, prioritize closing bins
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
