    // If post_residual is < 10, it is likely unusable for future items (range 10..100).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64);
    }

    // 2. Lookahead Synergy: If the next item can fit perfectly or near-perfectly into the current post_residual,
    // prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next == 0 {
            score -= 40.0; // Perfect fit reward
        } else if gap_after_next < 10 {
            score += 20.0; // Avoid creating a tiny sliver after the next item
        }
    }

    // 3. Open Bins Pressure: Discourage opening new bins unless necessary.
