        score += (open_bins_count as f64 * 15.0) + 40.0;
    }

    // 4. Mean Residual Balancing: Avoid creating bins that are significantly below the current average.
    // If post_residual is much smaller than the mean, it's a "tight" bin, which is generally good.
    if (post_residual as f64) < mean_residual {
