pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating 'dead zones' (small residuals < 10) that are hard to fill
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: if next_item_size is large, favor keeping larger residuals (higher post_res)
    // If next_item_size is small, favor filling the current bin tightly
    if next_item_size > 0 {
        let lookahead_diff = (next_item_size as f64 - post_res).abs();
        score += lookahead_diff * 0.5 * (1.0 - progress);
    }

    // Heuristic for opening new bins:
    // If this is an empty bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // Only open a new bin if the current packing is inefficient across the board
        // or if fitting_bins_count is zero (forced)
        if fitting_bins_count == 0 {
            score = 5.0; // Highly preferred when no other option
        } else {
            // Penalize opening new bins as the stream progresses to consolidate packing
            score = 40.0 + (progress * 60.0) + (open_bins_count as f64 * 2.0);
        }
    } else {
        // If it's an existing bin, favor those that align with the mean density
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for opening a new bin if other bins are available
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0;
    }

    // Best-Fit logic: punish larger post_residuals
    // Harmonic weight: smaller residuals are better if they are "tight" (close to 0)
    // We reward residuals that are multiples of 5 or 10, as they likely leave room for common item sizes
    if post_residual % 5 == 0 {
        score -= 2.5;
    }

    // Lookahead logic: if the next item can fit in the current post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Further reward if the resulting space is very small (perfect packing)
        if post_residual - next_item_size < 5 {
            score -= 10.0;
        }
    }

    // Penalty for leaving "unusable" space (e.g., < 10) if the stream is ongoing
    // and we aren't near the end of the items
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Favor bins that maintain a mean residual close to the average item size (estimated 40)
    // This helps keep the bin distribution uniform
    let residual_diff = (post_residual as f64 - (bin_capacity as f64 - 40.0)).abs();
    score += residual_diff * 0.1;

    // Penalize the "last chance" bin to prevent early fragmentation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Strategy: Minimize "dead space" (post_residual) while penalizing fragmentation.
    // We prioritize Best-Fit (post_residual near 0) but add a heavy penalty for 
    // leaving "unusable gaps" (gaps < 10, since 10 is the minimum item size).

    let mut score = post_residual as f64;

    // 1. Penalize unusable gaps: if gap < 10, it's likely dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Open bin pressure: discourage opening too many bins early.
    // If this is a new bin, penalize based on the number of existing bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 1.5) + 25.0;
    }

    // 3. Lookahead optimization: If next_item_size is known, favor bins that 
    // can accommodate both current and next items.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // Reward bins that can fit the next item
        } else {
            score += 10.0; // Penalize bins that will force a new bin for the next item
        }
    }

    // 4. Fitting constraints: If this is the only bin that fits the current item, 
    // heavily reward choosing it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
