    // Heuristic #1356: Harmonic-Residual Balancing
    // We prioritize keeping the residual small (Best Fit), but penalize 
    // "dangling" residuals that are too small to fit future items (Dead Space).

    let mut score = post_residual as f64;

    // 1. Penalize creating "Dead Space" (residuals < 10, as items are >= 1)
    // If we leave a tiny gap, it's likely wasted unless it is exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 / (post_residual as f64);
    }

    // 2. Lookahead Coupling: If the next item fits into the current post_residual, 
    // strongly reward this bin to maximize packing density.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 1.5;
    }

    // 3. Harmonic Thresholding: Favor bins that align with the mean residual 
    // to keep the bin distribution uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 4. New Bin Decision Logic: 
    // If this is a new bin (bin_residual == bin_capacity), penalize it 
    // unless no other fitting bins exist or the current fit is extremely poor.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if other options exist
            score += 60.0;
        } else {
            // Neutralize score for necessary new bin
            score = 20.0;
        }
    }

    // 5. Progression Scaling: As the stream nears the end, become more 
    // aggressive about closing bins (Best Fit).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize small gaps that cannot fit common items.
    // Gaps < 10 are almost always wasted. Gaps between 10-20 are risky.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // 2. Lookahead Coupling: If next_item_size is large, avoid leaving a residual that is too small for it.
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 25.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
    }

    // 3. Global Bin Pressure: If this is the only fitting bin, prioritize it to prevent unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 4. Open Bin Management: Penalize opening a new bin if we have many bins already open.
    // This encourages filling existing bins rather than fragmenting space across many bins.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64 * 5.0);
    }

    // 5. Residual Balancing: Favor bins that stay close to the mean_residual to keep space distribution uniform.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // 1. Base Score: The post-placement residual (Best Fit approach).
    let mut score = post_residual as f64;

    // 2. Penalty for creating "dead space": If post_residual is small but > 0, 
    // it is often worse than leaving it empty (0) or having a larger residual.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 3. Lookahead Logic: If the next item fits perfectly in the post_residual, 
    // significantly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        if diff < 5.0 {
            score -= 40.0;
        } else {
            score -= 15.0;
        }
    }

    // 4. Global State Awareness: If we are near the end of the stream, 
    // be more conservative with opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have many fitting options.
        score += 30.0 + (fitting_bins_count as f64 * 5.0);
        // Reduce penalty as we near the end of the stream to avoid last-item overflow.
        score -= (progress * 20.0);
    }

    // 5. Balance density: Favor bins that stay near the mean residual of the system.
    let residual_deviation = (post_residual as f64 - mean_residual).abs();
    score += residual_deviation * 0.2;

    score
}
